const e=[{key:"caie-bio-topic1",name:"CAIE生物 · Topic 1 生物的特征与分类",description:"生物的特征与分类 · 42 个术语定义（IGCSE 生物）",words:[{word:"Amino acids",phonetic:"",meaning:"Small molecules from which proteins are synthesised.",example:"氨基酸",image_url:"",emoji:"🧬"},{word:"Amphibia",phonetic:"",meaning:"A class of vertebrates - including frogs, toads and newts - that are poikilothermic. They have four limbs, of which hind feet are often webbed. Amphibia have lungs and moist skin for breathing. They reproduce sexually via external fertilisation.",example:"两栖类",image_url:"",emoji:"🧬"},{word:"Animal (kingdom)",phonetic:"",meaning:"A biological kingdom consisting of multicellular organisms that do not have a cell wall or chloroplasts. They ingest and digest food for energy.",example:"动物界",image_url:"",emoji:"🧬"},{word:"Arachnids",phonetic:"",meaning:"A class of arthropods including spiders, scorpions, ticks and mites. Arachnids have a segmented body (divided into the cephalothorax and abdomen), four pairs of jointed legs and several pairs of simple eyes.",example:"蛛形纲",image_url:"",emoji:"🧬"},{word:"Arthropods",phonetic:"",meaning:"A phylum consisting of invertebrate animals with jointed limbs, segmented bodies and a hard external skeleton (cuticle). Arthropods include crustaceans, myriapods, arachnids and insects.",example:"节肢动物门",image_url:"",emoji:"🧬"},{word:"Binomial system",phonetic:"",meaning:"A universal system for naming organisms using their genus and species.",example:"双名法",image_url:"",emoji:"🧬"},{word:"Birds",phonetic:"",meaning:"A class of vertebrates that are homoiothermic. Birds have four limbs (the forelimbs form wings), and beaked jaws. They have an outer covering of feathers over most of the body and scales on the legs and toes. Fertilisation occurs internally, with the female laying hard-shelled eggs.",example:"鸟类",image_url:"",emoji:"🧬"},{word:"Cell membrane",phonetic:"",meaning:"The partially permeable barrier that surrounds a cell.",example:"细胞膜",image_url:"",emoji:"🧬"},{word:"Classification",phonetic:"",meaning:"The organisation of organisms into groups based on their characteristics and structure. Classification systems may also reflect evolutionary relationships between organisms.",example:"分类",image_url:"",emoji:"🧬"},{word:"Crustacea",phonetic:"",meaning:"A class of arthropods including crabs, lobsters, prawns, shrimps, the water louse and woodlice. They have compound eyes and two pairs of antennae.",example:"甲壳纲",image_url:"",emoji:"🧬"},{word:"Cytoplasm",phonetic:"",meaning:"The jelly-like component of cells that contains sub-cellular structures, dissolved nutrients and salts.",example:"细胞质",image_url:"",emoji:"🧬"},{word:"Dichotomous key",phonetic:"",meaning:"A tool consisting of a series of choices (i.e. features) used to identify an unknown organism.",example:"二歧检索表",image_url:"",emoji:"🧬"},{word:"Dicotyledons",phonetic:"",meaning:"Plants that produce seeds that contain two cotyledons (embryonic leaves), resulting in two primary leaves.",example:"双子叶植物",image_url:"",emoji:"🧬"},{word:"DNA",phonetic:"",meaning:"A double-stranded polymer, wound to form a double helix, that carries the genetic code.",example:"脱氧核糖核酸（DNA）",image_url:"",emoji:"🧬"},{word:"DNA base sequence",phonetic:"",meaning:"The sequence of bases in a molecule of DNA which can be used as an accurate method of classification. The more similar the base sequences, the more closely related the organisms.",example:"DNA碱基序列",image_url:"",emoji:"🧬"},{word:"Enzymes",phonetic:"",meaning:"Biological catalysts that increase the rate of reaction in living organisms.",example:"酶",image_url:"",emoji:"🧬"},{word:"Excretion",phonetic:"",meaning:"The removal of the waste products of metabolism and substances in excess of requirements from the body.",example:"排泄",image_url:"",emoji:"🧬"},{word:"Ferns",phonetic:"",meaning:"A group of vascular land plants that have neither seeds nor flowers and reproduce via spores from numerous sporangia. They have simple, fleshy underground stems known as rhizomes.",example:"蕨类植物",image_url:"",emoji:"🧬"},{word:"Fish",phonetic:"",meaning:"A class of vertebrates that are poikilothermic. They have a smooth-streamlined shape with fins for movement and are covered in overlapping scales. Fish have gills for breathing and reproduce sexually, with fertilisation normally occurring externally.",example:"鱼类",image_url:"",emoji:"🧬"},{word:"Fungus",phonetic:"",meaning:"A biological kingdom consisting of organisms made up of hyphae (long, branching filamentous structures). They reproduce asexually by producing spores.",example:"真菌",image_url:"",emoji:"🧬"},{word:"Growth",phonetic:"",meaning:"An increase in size or dry mass that is permanent. This may be due to an increase in the number or size of cells.",example:"生长",image_url:"",emoji:"🧬"},{word:"Homoiothermic",phonetic:"",meaning:"Describes an organism that is warm-blooded and whose body temperature is internally regulated.",example:"恒温的",image_url:"",emoji:"🧬"},{word:"Insects",phonetic:"",meaning:"A diverse class of arthropods including butterflies, bees, beetles, mosquitoes, houseflies, greenfly and earwigs. They have segmented bodies (consisting of a head, thorax and abdomen), three pairs of jointed legs, one pair of antennae, compound eyes and normally two pairs of wings.",example:"昆虫纲",image_url:"",emoji:"🧬"},{word:"Kingdom",phonetic:"",meaning:"The largest group of organisms identified by biologists. There are five kingdoms: Animal, Plant, Fungus, Prokaryote and Protoctist.",example:"界",image_url:"",emoji:"🧬"},{word:"Mammals",phonetic:"",meaning:"A class of vertebrates that are homoiothermic. They have four limbs and are characterised by the presence of hair or fur, and mammary glands. Mammals produce live young.",example:"哺乳类",image_url:"",emoji:"🧬"},{word:"Monocotyledons",phonetic:"",meaning:"Plants that produce seeds that contain one cotyledon (embryonic leaf), resulting in one primary leaf.",example:"单子叶植物",image_url:"",emoji:"🧬"},{word:"Movement",phonetic:"",meaning:"A change in position due to the action of an organism or part of an organism.",example:"运动",image_url:"",emoji:"🧬"},{word:"Myriapods",phonetic:"",meaning:"A class of arthropods consisting of millipedes and centipedes. They have a segmented body, ten or more pairs of jointed legs, one pair of antennae and simple eyes.",example:"多足纲",image_url:"",emoji:"🧬"},{word:"Nutrition",phonetic:"",meaning:"The process by which living organisms take in materials necessary for growth, development and energy. Animals require organic compounds, ions and water. Plants require light, carbon dioxide, ions and water.",example:"营养",image_url:"",emoji:"🧬"},{word:"Plant (kingdom)",phonetic:"",meaning:"A biological kingdom consisting of multicellular organisms that have a cellulose cell wall and can photosynthesise.",example:"植物界",image_url:"",emoji:"🧬"},{word:"Poikilothermic",phonetic:"",meaning:"Describes an organism that is cold-blooded and whose body temperature varies with the temperature of the external environment.",example:"变温的",image_url:"",emoji:"🧬"},{word:"Prokaryote",phonetic:"",meaning:"A biological kingdom consisting of unicellular bacteria which lack a nucleus and membrane-bound organelles.",example:"原核生物",image_url:"",emoji:"🧬"},{word:"Protein",phonetic:"",meaning:"A large molecule that is synthesised from amino acids.",example:"蛋白质",image_url:"",emoji:"🧬"},{word:"Protoctist",phonetic:"",meaning:"A biological kingdom consisting of unicellular eukaryotes.",example:"原生生物",image_url:"",emoji:"🧬"},{word:"Reproduction",phonetic:"",meaning:"The processes that make more of the same kind of organism",example:"生殖",image_url:"",emoji:"🧬"},{word:"Reptiles",phonetic:"",meaning:"A class of vertebrates that are poikilothermic. They have four limbs and dry, scaly skin. Reptiles reproduce sexually, with fertilisation occurring internally.",example:"爬行类",image_url:"",emoji:"🧬"},{word:"Respiration",phonetic:"",meaning:"Chemical reactions that take place inside cells and release energy from the breakdown of nutrient molecules. This energy is used in metabolism.",example:"呼吸作用",image_url:"",emoji:"🧬"},{word:"Ribosomes",phonetic:"",meaning:"Sub-cellular structures that are the site for protein synthesis.",example:"核糖体",image_url:"",emoji:"🧬"},{word:"Sensitivity",phonetic:"",meaning:"The ability to sense and respond to internal and external stimuli in the environment.",example:"敏感性",image_url:"",emoji:"🧬"},{word:"Species",phonetic:"",meaning:"A group of similar organisms that can interbreed to produce fertile offspring.",example:"物种",image_url:"",emoji:"🧬"},{word:"Vertebrates",phonetic:"",meaning:"A group of animals which have a vertebral column (otherwise known as the ‘spinal column’ or ‘spine’). Vertebrates include fish, amphibia, reptiles, birds and mammals.",example:"脊椎动物",image_url:"",emoji:"🧬"},{word:"Virus",phonetic:"",meaning:"A non-living microorganism that consists of genetic material surrounded by a protein coat.",example:"病毒",image_url:"",emoji:"🧬"}]},{key:"caie-bio-topic2",name:"CAIE生物 · Topic 2 生物体的结构层次",description:"生物体的结构层次 · 29 个术语定义（IGCSE 生物）",words:[{word:"Acrosome",phonetic:"",meaning:"An organelle in the tip of a sperm that contains enzymes which digest the cells around an egg and the egg membrane.",example:"顶体",image_url:"",emoji:"🔬"},{word:"Cell",phonetic:"",meaning:"The basic building block of all living organisms.",example:"细胞",image_url:"",emoji:"🔬"},{word:"Cell membrane",phonetic:"",meaning:"A partially permeable barrier that surrounds the cell.",example:"细胞膜",image_url:"",emoji:"🔬"},{word:"Cell wall",phonetic:"",meaning:"An outer layer made of cellulose that strengthens plant cells.",example:"细胞壁",image_url:"",emoji:"🔬"},{word:"Chloroplast",phonetic:"",meaning:"An organelle in which photosynthesis occurs.",example:"叶绿体",image_url:"",emoji:"🔬"},{word:"Cilia",phonetic:"",meaning:"Hair-like structures found on ciliated cells that waft substances across the surface of tissue in one direction.",example:"纤毛",image_url:"",emoji:"🔬"},{word:"Ciliated cell",phonetic:"",meaning:"A type of epithelial cell that lines the surface of structures such as the respiratory tract and uterus. Ciliated cells are covered in tiny hair-like structures known as cilia.",example:"纤毛细胞",image_url:"",emoji:"🔬"},{word:"Cytoplasm",phonetic:"",meaning:"A thick solution of salts, water and proteins within the cell. It contains the cell’s organelles.",example:"细胞质",image_url:"",emoji:"🔬"},{word:"Egg cell",phonetic:"",meaning:"A specialised female sex cell involved in reproduction. It has a haploid nucleus which holds the genetic material of the cell and a large amount of cytoplasm containing nutrients for the growth of the early embryo.",example:"卵细胞",image_url:"",emoji:"🔬"},{word:"Gamete",phonetic:"",meaning:"A reproductive cell with half the chromosomes of normal cells.",example:"配子",image_url:"",emoji:"🔬"},{word:"Light microscope",phonetic:"",meaning:"A type of microscope that uses a series of lenses to magnify the visible light reflecting off a specimen. It has a low magnification and resolution.",example:"光学显微镜",image_url:"",emoji:"🔬"},{word:"Magnification",phonetic:"",meaning:"The number of times larger an image appears compared to the original object, calculated using the formula: image size = magnification × real size",example:"放大倍数",image_url:"",emoji:"🔬"},{word:"Micrometre (µm)",phonetic:"",meaning:"A quantitative unit of length. One micrometre is equal to ×10-6 metre.",example:"微米（µm）",image_url:"",emoji:"🔬"},{word:"Millimetre (mm)",phonetic:"",meaning:"A quantitative unit of length. One millimetre is equal to ×10-3 metre.",example:"毫米（mm）",image_url:"",emoji:"🔬"},{word:"Mitochondria",phonetic:"",meaning:"An organelle that is the site of aerobic respiration. Cells with high rates of metabolism require a large number of mitochondria.",example:"线粒体",image_url:"",emoji:"🔬"},{word:"Nerve cells",phonetic:"",meaning:"Specialised cells responsible for the transmission of nerve impulses to and from the brain and spinal cord.",example:"神经细胞",image_url:"",emoji:"🔬"},{word:"Nucleus",phonetic:"",meaning:"An organelle found in most plant and animal cells that contains the genetic material of the cell and controls the activities of the cell.",example:"细胞核",image_url:"",emoji:"🔬"},{word:"Organ",phonetic:"",meaning:"A group of specialised tissues working together to carry out a specific function.",example:"器官",image_url:"",emoji:"🔬"},{word:"Organelle",phonetic:"",meaning:"A specialised structure found inside a cell.",example:"细胞器",image_url:"",emoji:"🔬"},{word:"Organ system",phonetic:"",meaning:"A group of specialised organs working together to carry out a specific function.",example:"器官系统",image_url:"",emoji:"🔬"},{word:"Palisade mesophyll cells",phonetic:"",meaning:"Plant cells located below the upper epidermis. They receive a large amount of light so contain a high concentration of chloroplasts for photosynthesis.",example:"栅栏叶肉细胞",image_url:"",emoji:"🔬"},{word:"Prokaryotic cell",phonetic:"",meaning:"A type of cell found in bacteria that does not contain a nucleus or membrane-bound organelles.",example:"原核细胞",image_url:"",emoji:"🔬"},{word:"Red blood cell",phonetic:"",meaning:"A type of blood cell that is anucleate and biconcave. It contains haemoglobin which enables the transport of oxygen and carbon dioxide to and from the tissues.",example:"红细胞",image_url:"",emoji:"🔬"},{word:"Ribosomes",phonetic:"",meaning:"Organelles that are the site for protein synthesis.",example:"核糖体",image_url:"",emoji:"🔬"},{word:"Root hair cells",phonetic:"",meaning:"Specialised cells responsible for the uptake of water and minerals from the soil.",example:"根毛细胞",image_url:"",emoji:"🔬"},{word:"Sperm cell",phonetic:"",meaning:"A specialised male sex cell involved in reproduction. It consists of a head containing the acrosome and haploid nucleus, a midpiece containing many mitochondria and a tail.",example:"精子细胞",image_url:"",emoji:"🔬"},{word:"Tissue",phonetic:"",meaning:"A group of specialised cells working together to carry out a specific function.",example:"组织",image_url:"",emoji:"🔬"},{word:"Vacuole",phonetic:"",meaning:"An organelle found in plant cells which stores cell sap and supports the cell.",example:"液泡",image_url:"",emoji:"🔬"},{word:"Xylem vessel",phonetic:"",meaning:"A transport tissue in plants that is specialised to transport water and dissolved minerals from the roots of the plant to the leaves.",example:"木质部导管",image_url:"",emoji:"🔬"}]},{key:"caie-bio-topic3",name:"CAIE生物 · Topic 3 物质进出细胞",description:"物质进出细胞 · 11 个术语定义（IGCSE 生物）",words:[{word:"Active transport",phonetic:"",meaning:"The movement of substances from a low concentration to a higher concentration (against the concentration gradient) across a membrane, with the use of energy from respiration.",example:"主动运输",image_url:"",emoji:"💧"},{word:"Concentration gradient",phonetic:"",meaning:"The difference in concentration between two areas. The greater the concentration gradient, the faster the rate of diffusion.",example:"浓度梯度",image_url:"",emoji:"💧"},{word:"Diffusion",phonetic:"",meaning:"The net spreading out of particles from a high concentration to a lower concentration (down their concentration gradient). Diffusion is as a result of the kinetic energy of the random movement of particles (passive).",example:"扩散",image_url:"",emoji:"💧"},{word:"Diffusion distance",phonetic:"",meaning:"The distance that substances must diffuse. The smaller the diffusion distance, the faster the rate of diffusion.",example:"扩散距离",image_url:"",emoji:"💧"},{word:"Flaccid",phonetic:"",meaning:"Describes a plant cell that has been placed in a more concentrated solution. Water leaves the cell by osmosis. The volume decreases and the cytoplasm pulls away from the cell wall.",example:"软弱的（细胞失水）",image_url:"",emoji:"💧"},{word:"Osmosis",phonetic:"",meaning:"The diffusion of water across a partially permeable membrane.",example:"渗透作用",image_url:"",emoji:"💧"},{word:"Plasmolysis",phonetic:"",meaning:"The process by which the cytoplasm pulls away from the cell wall as a result of water loss from the cell.",example:"质壁分离",image_url:"",emoji:"💧"},{word:"Surface area",phonetic:"",meaning:"The total area occupied by the surface of an object. The larger the surface area, the faster the rate of diffusion.",example:"表面积",image_url:"",emoji:"💧"},{word:"Turgid",phonetic:"",meaning:"Describes a plant cell that has been placed in a more dilute solution. Water enters the cell by osmosis. The volume increases and the cytoplasm pushes against the cell wall.",example:"膨胀的（细胞吸水）",image_url:"",emoji:"💧"},{word:"Turgor pressure",phonetic:"",meaning:"The pressure exerted by fluid within a cell which pushes the cell membrane against the inelastic cell wall.",example:"膨压",image_url:"",emoji:"💧"},{word:"Water potential",phonetic:"",meaning:"A measure of the tendency of water molecules to move from one area to another.",example:"水势",image_url:"",emoji:"💧"}]},{key:"caie-bio-topic4",name:"CAIE生物 · Topic 4 生物分子",description:"生物分子 · 21 个术语定义（IGCSE 生物）",words:[{word:"Amino acids",phonetic:"",meaning:"Small molecules from which proteins are synthesised.",example:"氨基酸",image_url:"",emoji:"🧪"},{word:"Benedict’s test",phonetic:"",meaning:"A chemical test used to test for reducing sugars that produces a different colour based on the amount of reducing sugar present.",example:"班氏试剂检测（还原糖）",image_url:"",emoji:"🧪"},{word:"Biuret test",phonetic:"",meaning:"A chemical test that produces a purple colour in the presence of protein.",example:"双缩脲试剂检测（蛋白质）",image_url:"",emoji:"🧪"},{word:"Carbohydrate",phonetic:"",meaning:"A large molecule that is synthesised from simple sugars.",example:"碳水化合物",image_url:"",emoji:"🧪"},{word:"Cellulose",phonetic:"",meaning:"A type of carbohydrate made from many glucose molecules joined together. It is the main component of the cell wall in plants.",example:"纤维素",image_url:"",emoji:"🧪"},{word:"Complementary base pairing",phonetic:"",meaning:"Describes how cross-links form between complementary base pairs. A pairs with T and C pairs with G.",example:"碱基互补配对",image_url:"",emoji:"🧪"},{word:"DCPIP test",phonetic:"",meaning:"A chemical test for vitamin C. Upon the addition of DCPIP, a colour change from blue to colourless indicates a positive test.",example:"DCPIP检测（维生素C）",image_url:"",emoji:"🧪"},{word:"DNA",phonetic:"",meaning:"A double-stranded polymer of nucleotides, wound to form a double helix, that carries the genetic code.",example:"脱氧核糖核酸（DNA）",image_url:"",emoji:"🧪"},{word:"Emulsion test",phonetic:"",meaning:"A chemical test that produces a cloudy emulsion when performed on lipids.",example:"乳浊液检测（脂肪）",image_url:"",emoji:"🧪"},{word:"Fats",phonetic:"",meaning:"Lipids that are solid at room temperature.",example:"脂肪",image_url:"",emoji:"🧪"},{word:"Fatty acids",phonetic:"",meaning:"Small molecules from which fats are synthesised (along with glycerol). A molecule of fat contains three fatty acid molecules.",example:"脂肪酸",image_url:"",emoji:"🧪"},{word:"Glucose",phonetic:"",meaning:"A small molecule from which many carbohydrates (e.g. glycogen, starch, cellulose) are synthesised.",example:"葡萄糖",image_url:"",emoji:"🧪"},{word:"Glycerol",phonetic:"",meaning:"A component of fat molecules.",example:"甘油",image_url:"",emoji:"🧪"},{word:"Glycogen",phonetic:"",meaning:"A type of carbohydrate made from many glucose molecules joined together. It serves as an energy store in animals.",example:"糖原",image_url:"",emoji:"🧪"},{word:"Iodine test",phonetic:"",meaning:"A chemical test that produces a blue/black colour when iodine solution is added to a sample containing starch.",example:"碘液检测（淀粉）",image_url:"",emoji:"🧪"},{word:"Lipids",phonetic:"",meaning:"A group of large molecules that are synthesised from fatty acids and glycerol.",example:"脂质",image_url:"",emoji:"🧪"},{word:"Nucleotides",phonetic:"",meaning:"The monomers of DNA consisting of a five-carbon sugar, a phosphate group and one of four chemical bases (A, T, C, G) attached to the sugar.",example:"核苷酸",image_url:"",emoji:"🧪"},{word:"Oils",phonetic:"",meaning:"Lipids that are liquid at room temperature.",example:"油",image_url:"",emoji:"🧪"},{word:"Protein",phonetic:"",meaning:"A large molecule that is synthesised from amino acids.",example:"蛋白质",image_url:"",emoji:"🧪"},{word:"Solvent",phonetic:"",meaning:"A substance which other solutes are dissolved in e.g. water.",example:"溶剂",image_url:"",emoji:"🧪"},{word:"Starch",phonetic:"",meaning:"A type of carbohydrate made from many glucose molecules joined together. It serves as an energy store in plants.",example:"淀粉",image_url:"",emoji:"🧪"}]},{key:"caie-bio-topic5",name:"CAIE生物 · Topic 5 酶",description:"酶 · 7 个术语定义（IGCSE 生物）",words:[{word:"Active site",phonetic:"",meaning:"A specific region of an enzyme where the substrate binds and the reaction takes place.",example:"活性位点",image_url:"",emoji:"⚗️"},{word:"Catalyst",phonetic:"",meaning:"A substance that increases the rate of a chemical reaction without being changed itself.",example:"催化剂",image_url:"",emoji:"⚗️"},{word:"Denaturation",phonetic:"",meaning:"Exposure to high temperatures or extremes of pH, produces a permanent change in the shape of an enzyme’s active site that prevents the binding of a substrate.",example:"变性",image_url:"",emoji:"⚗️"},{word:"Enzyme",phonetic:"",meaning:"A biological catalyst that increases the rate of reactions in living organisms.",example:"酶",image_url:"",emoji:"⚗️"},{word:"Enzyme-substrate complex",phonetic:"",meaning:"The temporary complex formed when the substrate binds to the active site of the enzyme.",example:"酶-底物复合物",image_url:"",emoji:"⚗️"},{word:"Rate of reaction",phonetic:"",meaning:"The speed at which reactants are converted into products.",example:"反应速率",image_url:"",emoji:"⚗️"},{word:"Substrate specificity",phonetic:"",meaning:"The ability of an enzyme to catalyse only a specific reaction or set of reactions which have substrates complementary to the shape of the enzyme.",example:"底物特异性",image_url:"",emoji:"⚗️"}]},{key:"caie-bio-topic6",name:"CAIE生物 · Topic 6 植物营养",description:"植物营养 · 20 个术语定义（IGCSE 生物）",words:[{word:"Carbohydrate",phonetic:"",meaning:"A large molecule that is synthesised from simple sugars.",example:"碳水化合物",image_url:"",emoji:"🌿"},{word:"Chlorophyll",phonetic:"",meaning:"A photosynthetic pigment found in chloroplasts that transfers light energy into chemical energy in molecules.",example:"叶绿素",image_url:"",emoji:"🌿"},{word:"Chloroplast",phonetic:"",meaning:"An organelle found in plants and algae that is the site for photosynthesis.",example:"叶绿体",image_url:"",emoji:"🌿"},{word:"Gaseous exchange",phonetic:"",meaning:"The exchange of respiratory gases between an organism and its environment.",example:"气体交换",image_url:"",emoji:"🌿"},{word:"Guard cells",phonetic:"",meaning:"Cells that surround the stomata and change shape depending on the volume of water. They control the rate of transpiration by becoming turgid or flaccid, opening or closing stomata.",example:"保卫细胞",image_url:"",emoji:"🌿"},{word:"Hydrogencarbonate indicator",phonetic:"",meaning:"An indicator that changes colour depending on the concentration of carbon dioxide and the resulting pH of the solution.",example:"碳酸氢盐指示剂",image_url:"",emoji:"🌿"},{word:"Limiting factor",phonetic:"",meaning:"A variable that is in short supply and limits the rate of a particular reaction.",example:"限制因素",image_url:"",emoji:"🌿"},{word:"Lower epidermis",phonetic:"",meaning:"A layer of cells on the leaf’s lower surface that contains stomata and guard cells.",example:"下表皮",image_url:"",emoji:"🌿"},{word:"Magnesium ions",phonetic:"",meaning:"A type of mineral element required by plants for the production of chlorophyll. If a plant is deficient in magnesium ions its leaves turn yellow in a process known as chlorosis.",example:"镁离子",image_url:"",emoji:"🌿"},{word:"Nitrate ions",phonetic:"",meaning:"A type of mineral element required by plants for the production of amino acids. If a plant is deficient in nitrate ions it exhibits stunted growth. It’s lower leaves become yellow and its upper leaves turn pale green.",example:"硝酸根离子",image_url:"",emoji:"🌿"},{word:"Palisade mesophyll",phonetic:"",meaning:"The main photosynthetic tissue in plants located below the upper epidermis. It receives the most light so contains the greatest concentration of chloroplasts.",example:"栅栏叶肉",image_url:"",emoji:"🌿"},{word:"Phloem",phonetic:"",meaning:"A transport tissue found in plants that is specialised to transport sugars from the leaves to the rest of the plant in both directions.",example:"韧皮部",image_url:"",emoji:"🌿"},{word:"Photosynthesis",phonetic:"",meaning:"A reaction that takes place inside photosynthetic organisms (e.g. plants, algae) and manufactures carbohydrates from raw materials using light energy. Overall in the presence of light and chlorophyll: carbon dioxide + water ⟶ glucose + oxygen 6CO2 + 6H2O ⟶ C6H12O6 + 6O2",example:"光合作用",image_url:"",emoji:"🌿"},{word:"Spongy mesophyll",phonetic:"",meaning:"A type of loosely packed mesophyll tissue with air pockets, which is specialised for gas exchange. It contains some chloroplasts for photosynthesis.",example:"海绵叶肉",image_url:"",emoji:"🌿"},{word:"Starch",phonetic:"",meaning:"A type of carbohydrate made from many glucose molecules joined together. It serves as an energy store in plants.",example:"淀粉",image_url:"",emoji:"🌿"},{word:"Stomata",phonetic:"",meaning:"Small holes found on the surface of a plant (typically leaves) that can be opened or closed by guard cells to control water loss and gas exchange.",example:"气孔",image_url:"",emoji:"🌿"},{word:"Sucrose",phonetic:"",meaning:"A soluble sugar produced from the breakdown of starch in plants. It can be stored, used in respiration or used to synthesise other substances.",example:"蔗糖",image_url:"",emoji:"🌿"},{word:"Upper epidermis",phonetic:"",meaning:"A layer of transparent cells that allows light to strike the palisade mesophyll tissue.",example:"上表皮",image_url:"",emoji:"🌿"},{word:"Vascular bundle",phonetic:"",meaning:"Part of the transport system in vascular plants that consists of xylem and phloem tissue.",example:"维管束",image_url:"",emoji:"🌿"},{word:"Xylem",phonetic:"",meaning:"A transport tissue in plants that is specialised to transport water and dissolved minerals from the roots of the plant to the leaves.",example:"木质部",image_url:"",emoji:"🌿"}]},{key:"caie-bio-topic7",name:"CAIE生物 · Topic 7 人体营养",description:"人体营养 · 56 个术语定义（IGCSE 生物）",words:[{word:"Absorption",phonetic:"",meaning:"The movement of useful substances through the wall of the intestine into the bloodstream.",example:"吸收",image_url:"",emoji:"🍽️"},{word:"Alimentary canal",phonetic:"",meaning:"A long, hollow, muscular tube running through the body where digestion and absorption takes place.",example:"消化道",image_url:"",emoji:"🍽️"},{word:"Amylase",phonetic:"",meaning:"An enzyme found in saliva and pancreatic juice that breaks down starch to simpler sugars (i.e. maltose).",example:"淀粉酶",image_url:"",emoji:"🍽️"},{word:"Anus",phonetic:"",meaning:"The opening at the far end of the alimentary canal that controls egestion.",example:"肛门",image_url:"",emoji:"🍽️"},{word:"Assimilation",phonetic:"",meaning:"The movement of simple food molecules into the cells of the body where they are used.",example:"同化作用",image_url:"",emoji:"🍽️"},{word:"Bile",phonetic:"",meaning:"A green, watery fluid produced by the liver that is stored in the gallbladder and secreted via the bile duct into the duodenum. It consists of bile salts which emulsify fats, increasing the surface area for lipase action, and an alkaline fluid which neutralises gastric juices from the stomach.",example:"胆汁",image_url:"",emoji:"🍽️"},{word:"Calcium",phonetic:"",meaning:"A mineral salt found in milk, cheese, eggs and fresh green vegetables that is required to maintain healthy teeth and bones, for muscle contraction and for blood clotting.",example:"钙",image_url:"",emoji:"🍽️"},{word:"Canines",phonetic:"",meaning:"Teeth with a pointed tip positioned either side of the incisors that are adapted for cutting pieces of food.",example:"犬齿",image_url:"",emoji:"🍽️"},{word:"Carbohydrates",phonetic:"",meaning:"A class of food that is used as an energy source in cells. Carbohydrates are abundant in potatoes, bread, pasta, rice etc.",example:"碳水化合物",image_url:"",emoji:"🍽️"},{word:"Cement",phonetic:"",meaning:"A tissue covering the surface of the root that allows connection of the tooth to the bony socket in the jaw.",example:"牙骨质",image_url:"",emoji:"🍽️"},{word:"Chemical digestion",phonetic:"",meaning:"A type of digestion that involves breaking down large, insoluble molecules into smaller, soluble molecules using enzymes.",example:"化学性消化",image_url:"",emoji:"🍽️"},{word:"Colon",phonetic:"",meaning:"The first section of the large intestine that reabsorbs water and bile salts from the waste material.",example:"结肠",image_url:"",emoji:"🍽️"},{word:"Dentine",phonetic:"",meaning:"A hard bony tissue underlying the enamel. It is softer than enamel.",example:"牙本质",image_url:"",emoji:"🍽️"},{word:"Duodenum",phonetic:"",meaning:"The first section of the small intestine which receives pancreatic juice for the chemical digestion of proteins, lipids and starch, and the neutralisation of stomach acid. It also receives bile from the gall bladder.",example:"十二指肠",image_url:"",emoji:"🍽️"},{word:"Egestion",phonetic:"",meaning:"The removal of undigested waste material as faeces from the body.",example:"排遗",image_url:"",emoji:"🍽️"},{word:"Enamel",phonetic:"",meaning:"The hard outer coating of the crown of the tooth.",example:"牙釉质",image_url:"",emoji:"🍽️"},{word:"Fats",phonetic:"",meaning:"A class of food that has a variety of roles in organisms including insulation, structure, protection of organs and energy storage. Animal fats are abundant in meat, milk, cheese and egg yolk. Plant fats are found as oils in fruits and seeds and are used to make margarine.",example:"脂肪",image_url:"",emoji:"🍽️"},{word:"Fibre",phonetic:"",meaning:"A complex carbohydrate found in plant-based foods that provides bulk, softening the faeces and supporting regular bowel movements. A diet lacking in fibre may result in constipation.",example:"膳食纤维",image_url:"",emoji:"🍽️"},{word:"Gall bladder",phonetic:"",meaning:"An organ that stores bile produced in the liver. It secretes bile into the duodenum via the bile duct.",example:"胆囊",image_url:"",emoji:"🍽️"},{word:"Gastric juice",phonetic:"",meaning:"A digestive juice secreted from glands in the stomach lining that contains proteases for the chemical digestion of proteins to amino acids. Hydrochloric acid dissolves in gastric juice, forming a weak solution.",example:"胃液",image_url:"",emoji:"🍽️"},{word:"Gum",phonetic:"",meaning:"The tissue that overlies the jaw bone inside of the mouth.",example:"牙龈",image_url:"",emoji:"🍽️"},{word:"Hydrochloric acid",phonetic:"",meaning:"A chemical found in gastric juice that kills harmful microorganisms in food (via enzyme denaturation) and provides an optimum pH for enzyme (pepsin) activity.",example:"盐酸",image_url:"",emoji:"🍽️"},{word:"Incisors",phonetic:"",meaning:"Chisel-shaped teeth at the front of the mouth adapted for cutting pieces of food.",example:"门齿",image_url:"",emoji:"🍽️"},{word:"Ingestion",phonetic:"",meaning:"The process by which organisms take food and drink into their bodies through the mouth.",example:"摄入",image_url:"",emoji:"🍽️"},{word:"Iron",phonetic:"",meaning:"A mineral salt found in red meat, eggs, nuts, wholegrains and fresh green vegetables that is required for the production of haemoglobin in red blood cells.",example:"铁",image_url:"",emoji:"🍽️"},{word:"Lacteals",phonetic:"",meaning:"The lymphatic vessels of the small intestine through which digested fats enter the lymphatic system.",example:"乳糜管",image_url:"",emoji:"🍽️"},{word:"Large intestine",phonetic:"",meaning:"An organ in the alimentary canal where water is reabsorbed from the waste material stored as faeces. It is made up of the colon and the rectum.",example:"大肠",image_url:"",emoji:"🍽️"},{word:"Lipase",phonetic:"",meaning:"An enzyme found in pancreatic juice that breaks down fats to fatty acids and glycerol.",example:"脂肪酶",image_url:"",emoji:"🍽️"},{word:"Liver",phonetic:"",meaning:"An organ that produces and secretes bile into the gallbladder. In the liver, digested foods (e.g. glucose) are assimilated and excess amino acids are deaminated.",example:"肝脏",image_url:"",emoji:"🍽️"},{word:"Malnutrition",phonetic:"",meaning:"A condition resulting from a diet lacking in, or too rich in nutrients.",example:"营养不良",image_url:"",emoji:"🍽️"},{word:"Maltase",phonetic:"",meaning:"An enzyme located on the membranes of the epithelial lining of the small intestine that breaks down maltose to glucose.",example:"麦芽糖酶",image_url:"",emoji:"🍽️"},{word:"Physical digestion",phonetic:"",meaning:"A type of digestion that involves physically breaking down food into smaller pieces. This increases the surface area for chemical digestion.",example:"物理性消化",image_url:"",emoji:"🍽️"},{word:"Microvilli",phonetic:"",meaning:"Protrusions of the epithelial cell membrane that provide a large surface area for absorption in the ileum.",example:"微绒毛",image_url:"",emoji:"🍽️"},{word:"Molars",phonetic:"",meaning:"Teeth with four or five cusps positioned at the back of the mouth. They have two or three roots and are adapted for chewing and grinding food.",example:"臼齿",image_url:"",emoji:"🍽️"},{word:"Mouth",phonetic:"",meaning:"The upper opening of the alimentary canal through which food enters the body. Mechanical and chemical digestion of starch take place here.",example:"口腔",image_url:"",emoji:"🍽️"},{word:"Oesophagus",phonetic:"",meaning:"A muscular tube that carries food from the mouth to the stomach by peristalsis.",example:"食道",image_url:"",emoji:"🍽️"},{word:"Pancreas",phonetic:"",meaning:"A gland situated behind the stomach that - via the pancreatic duct - secretes pancreatic juice into the duodenum.",example:"胰腺",image_url:"",emoji:"🍽️"},{word:"Pancreatic juice",phonetic:"",meaning:"A digestive juice secreted from the pancreas into the duodenum that contains a variety of enzymes for the chemical digestion of proteins, lipids and starch. It also contains sodium hydrogencarbonate which partially neutralises gastric juices from the stomach.",example:"胰液",image_url:"",emoji:"🍽️"},{word:"Pepsin",phonetic:"",meaning:"A protease enzyme secreted in the stomach that breaks down proteins into peptides.",example:"胃蛋白酶",image_url:"",emoji:"🍽️"},{word:"Peristalsis",phonetic:"",meaning:"The contraction of the circular muscle behind the bolus of food and the relaxation of the longitudinal muscle in front, forcing food down the gut.",example:"蠕动",image_url:"",emoji:"🍽️"},{word:"Premolars",phonetic:"",meaning:"Teeth with two cusps positioned behind the canines and in front of the molars. They have one or two roots and are adapted for tearing and grinding food.",example:"前臼齿",image_url:"",emoji:"🍽️"},{word:"Protease",phonetic:"",meaning:"An enzyme found in the stomach and small intestine that breaks down protein to amino acids. There are two types of protease enzymes: pepsin and trypsin.",example:"蛋白酶",image_url:"",emoji:"🍽️"},{word:"Proteins",phonetic:"",meaning:"A class of food that is required for the growth and repair of cells. Important sources of protein include lean meat, fish, milk, eggs, cheese, seeds and nuts.",example:"蛋白质",image_url:"",emoji:"🍽️"},{word:"Pulp cavity",phonetic:"",meaning:"The inner chamber of the tooth containing nerves, blood vessels and connective tissue, collectively known as pulp.",example:"牙髓腔",image_url:"",emoji:"🍽️"},{word:"Rectum",phonetic:"",meaning:"The second segment of the large intestine that stores faeces prior to egestion.",example:"直肠",image_url:"",emoji:"🍽️"},{word:"Saliva",phonetic:"",meaning:"An extracellular fluid secreted by the salivary glands that lubricates the food and causes small pieces to stick together to form a bolus. It also contains the enzyme amylase.",example:"唾液",image_url:"",emoji:"🍽️"},{word:"Salivary glands",phonetic:"",meaning:"Glands in the oral cavity that secrete saliva containing amylase for chemical digestion.",example:"唾液腺",image_url:"",emoji:"🍽️"},{word:"Scurvy",phonetic:"",meaning:"A deficiency disease resulting from a lack of vitamin C. Symptoms include bleeding under the skin and around gums, stunted growth in children, and very dry skin and hair.",example:"坏血病",image_url:"",emoji:"🍽️"},{word:"Small intestine",phonetic:"",meaning:"An organ in the alimentary canal where digestive enzymes and bile are mixed with food and the resulting digested materials are absorbed into the bloodstream. It is made up of the duodenum and the ileum.",example:"小肠",image_url:"",emoji:"🍽️"},{word:"Stomach",phonetic:"",meaning:"A muscular organ that receives food from the oesophagus. Mechanical digestion (mixing and grinding) and chemical digestion of protein occur here. It also contains hydrochloric acid to kill bacteria.",example:"胃",image_url:"",emoji:"🍽️"},{word:"Trypsin",phonetic:"",meaning:"A protease enzyme secreted by the pancreas (in an inactive form) into the duodenum where it is activated and breaks down proteins into peptides.",example:"胰蛋白酶",image_url:"",emoji:"🍽️"},{word:"Villi",phonetic:"",meaning:"Finger-like projections on the surface of the ileum wall that provide a large surface area for the absorption of food.",example:"绒毛",image_url:"",emoji:"🍽️"},{word:"Vitamin C",phonetic:"",meaning:"A vitamin found in citrus fruits, fresh green vegetables, tomatoes and potatoes that is required to protect cells and maintain healthy connective tissue, blood vessels, bones and cartilage. A deficiency in vitamin C leads to scurvy.",example:"维生素C",image_url:"",emoji:"🍽️"},{word:"Vitamin D",phonetic:"",meaning:"A vitamin found in dairy products, egg yolk and oily fish that is required to maintain healthy bones and teeth. The body can also manufacture vitamin D when exposed to sunlight.",example:"维生素D",image_url:"",emoji:"🍽️"},{word:"Vitamins",phonetic:"",meaning:"A group of organic substances which are required for the maintenance of health and the functioning of an organism’s metabolism.",example:"维生素",image_url:"",emoji:"🍽️"},{word:"Water",phonetic:"",meaning:"An essential nutrient found in the cytoplasm. It is an important solvent in organisms.",example:"水",image_url:"",emoji:"🍽️"}]},{key:"caie-bio-topic8",name:"CAIE生物 · Topic 8 植物体内的运输",description:"植物体内的运输 · 15 个术语定义（IGCSE 生物）",words:[{word:"Air spaces",phonetic:"",meaning:"Intracellular spaces within the spongy mesophyll layer of the leaf that enable gaseous exchange. The air becomes saturated with water vapour providing a high concentration gradient for its diffusion into the atmosphere.",example:"气腔",image_url:"",emoji:"🌱"},{word:"Cohesion (water movement)",phonetic:"",meaning:"The ‘sticking’ together of water molecules due to attractive forces between them. This enables water molecules to move up the xylem in a continuous stream.",example:"内聚力（水分运输）",image_url:"",emoji:"🌱"},{word:"Cortex",phonetic:"",meaning:"The tissue located between the epidermis and the vascular bundles in a plant stem or root. The cells of the cortex often store starch.",example:"皮层",image_url:"",emoji:"🌱"},{word:"Dicotyledons",phonetic:"",meaning:"Plants that produce seeds that contain two cotyledons (embryonic leaves), forming two primary leaves.",example:"双子叶植物",image_url:"",emoji:"🌱"},{word:"Phloem",phonetic:"",meaning:"A transport tissue found in plants that is specialised to transport sugars from the leaves to the rest of the plant in both directions.",example:"韧皮部",image_url:"",emoji:"🌱"},{word:"Root hair cells",phonetic:"",meaning:"Specialised cells responsible for the uptake of water and minerals from the soil. They have long hair-like extensions known as root hairs, which provide a large surface area for absorption of ions by active transport and water by osmosis.",example:"根毛细胞",image_url:"",emoji:"🌱"},{word:"Sinks (plants)",phonetic:"",meaning:"The regions of a plant that store or remove sugars e.g. roots, buds, fruits.",example:"库（植物）",image_url:"",emoji:"🌱"},{word:"Sources (plants)",phonetic:"",meaning:"The regions of a plant that produce sugars e.g. leaves, storage organs.",example:"源（植物）",image_url:"",emoji:"🌱"},{word:"Stomata",phonetic:"",meaning:"Small holes found on the surface of a plant that can be opened or closed by guard cells to control water loss and gas exchange.",example:"气孔",image_url:"",emoji:"🌱"},{word:"Surface area",phonetic:"",meaning:"The total area occupied by the surface of an object. The larger the surface area, the faster the rate of diffusion.",example:"表面积",image_url:"",emoji:"🌱"},{word:"Translocation",phonetic:"",meaning:"The movement of sugars (sucrose, amino acids, etc.) up and down a plant, from sources to sinks, via the phloem. Requires energy.",example:"易位（有机物运输）",image_url:"",emoji:"🌱"},{word:"Transpiration",phonetic:"",meaning:"Water loss from plant leaves and shoots via diffusion and evaporation. The rate of transpiration is affected by temperature and humidity.",example:"蒸腾作用",image_url:"",emoji:"🌱"},{word:"Vascular bundle",phonetic:"",meaning:"Part of the transport system in vascular plants that consists of xylem and phloem tissue.",example:"维管束",image_url:"",emoji:"🌱"},{word:"Wilting",phonetic:"",meaning:"The loss of rigidity of non-woody structures of plants. This is due to greater water loss via transpiration than is taken up by the roots.",example:"萎蔫",image_url:"",emoji:"🌱"},{word:"Xylem",phonetic:"",meaning:"A transport tissue in plants that is specialised to transport water and dissolved minerals from the roots of the plant to the leaves.",example:"木质部",image_url:"",emoji:"🌱"}]},{key:"caie-bio-topic9",name:"CAIE生物 · Topic 9 动物体内的运输",description:"动物体内的运输 · 33 个术语定义（IGCSE 生物）",words:[{word:"Aorta",phonetic:"",meaning:"The artery that takes oxygenated blood away from the heart to the body.",example:"主动脉",image_url:"",emoji:"🫀"},{word:"Artery",phonetic:"",meaning:"A type of blood vessel that carries blood away from the heart to the tissues, under high pressure. The walls of the arteries contain thick layers of smooth muscle and elastic fibres.",example:"动脉",image_url:"",emoji:"🫀"},{word:"Atria",phonetic:"",meaning:"The two upper chambers of the heart that receive blood from the veins and pump blood into the ventricles. The muscular walls of the atria are thinner than that of the ventricles.",example:"心房",image_url:"",emoji:"🫀"},{word:"Atrioventricular (AV) valves",phonetic:"",meaning:"The valves found between the atria and ventricles. They prevent the backflow of blood from the ventricles into the atria. There are two types of AV valves: bicuspid and tricuspid.",example:"房室瓣",image_url:"",emoji:"🫀"},{word:"Bicuspid valves",phonetic:"",meaning:"The atrioventricular valves found between the left atrium and left ventricle.",example:"二尖瓣（僧帽瓣）",image_url:"",emoji:"🫀"},{word:"Blood",phonetic:"",meaning:"A tissue containing red blood cells, white blood cells, platelets and plasma.",example:"血液",image_url:"",emoji:"🫀"},{word:"Blood clotting",phonetic:"",meaning:"A defence mechanism that prevents excessive blood loss and the entry of harmful microorganisms. It involves platelets and the conversion of fibrinogen to fibrin to form a mesh over the wound.",example:"血液凝固",image_url:"",emoji:"🫀"},{word:"Capillaries",phonetic:"",meaning:"Thin, narrow blood vessels that connect the arteries and veins. They are the site of exchange of substances between the blood and the tissues.",example:"毛细血管",image_url:"",emoji:"🫀"},{word:"Circulatory system",phonetic:"",meaning:"The transport system in mammals consisting of a pump, blood vessels and valves.",example:"循环系统",image_url:"",emoji:"🫀"},{word:"Coronary arteries",phonetic:"",meaning:"The arteries that supply the heart muscle with food and oxygen.",example:"冠状动脉",image_url:"",emoji:"🫀"},{word:"Coronary heart disease",phonetic:"",meaning:"A disease caused by the build-up of fatty deposits inside the coronary arteries, narrowing them and reducing blood flow to the heart tissue. Risk factors include a diet high in saturated fats, stress, lack of exercise, smoking, age, genetic predisposition and gender.",example:"冠心病",image_url:"",emoji:"🫀"},{word:"Double circulatory system",phonetic:"",meaning:"A circulatory system found in mammals in which the blood flows through the heart twice in two circuits. Blood is pumped from the heart to the lungs before returning to the heart. It is then pumped around the body, after which it returns to the heart again.",example:"双循环系统",image_url:"",emoji:"🫀"},{word:"Electrocardiogram (ECG)",phonetic:"",meaning:"A technique used to measure the spread of electrical activity through the heart by measuring tiny changes in the skin's electrical conductivity. This produces a trace which is used to detect abnormalities in heart rhythm.",example:"心电图（ECG）",image_url:"",emoji:"🫀"},{word:"Lymphocyte",phonetic:"",meaning:"A type of white blood cell that produces antibodies specific to a particular antigen.",example:"淋巴细胞",image_url:"",emoji:"🫀"},{word:"Phagocyte",phonetic:"",meaning:"A type of white blood cell that engulfs pathogens and digests them in a process known as phagocytosis.",example:"吞噬细胞",image_url:"",emoji:"🫀"},{word:"Phagocytosis",phonetic:"",meaning:"The process by which white blood cells (phagocytes) engulf and destroy pathogens.",example:"吞噬作用",image_url:"",emoji:"🫀"},{word:"Plasma",phonetic:"",meaning:"The main component of the blood that carries red blood cells. It is a yellow liquid containing blood cells, soluble nutrients, ions, carbon dioxide and hormones.",example:"血浆",image_url:"",emoji:"🫀"},{word:"Platelets",phonetic:"",meaning:"Small fragments of cells that are involved in blood clotting.",example:"血小板",image_url:"",emoji:"🫀"},{word:"Pulmonary arteries",phonetic:"",meaning:"The arteries that carry deoxygenated blood away from the heart to the lungs.",example:"肺动脉",image_url:"",emoji:"🫀"},{word:"Pulmonary veins",phonetic:"",meaning:"The veins that carry oxygenated blood from the lungs to the heart.",example:"肺静脉",image_url:"",emoji:"🫀"},{word:"Pulse rate",phonetic:"",meaning:"The number of pulses felt in an artery (e.g. radial artery) per minute.",example:"脉搏率",image_url:"",emoji:"🫀"},{word:"Red blood cell",phonetic:"",meaning:"A type of blood cell that is anucleate and biconcave. It contains haemoglobin which enables the transport of oxygen and carbon dioxide to and from the tissues.",example:"红细胞",image_url:"",emoji:"🫀"},{word:"Renal arteries",phonetic:"",meaning:"Blood vessels that carry oxygenated blood to the kidneys.",example:"肾动脉",image_url:"",emoji:"🫀"},{word:"Renal veins",phonetic:"",meaning:"Blood vessels that drain the kidneys.",example:"肾静脉",image_url:"",emoji:"🫀"},{word:"Semilunar valves",phonetic:"",meaning:"A pair of valves found between the ventricles and arteries. They prevent the backflow of blood from the arteries into the ventricles.",example:"半月瓣",image_url:"",emoji:"🫀"},{word:"Septum",phonetic:"",meaning:"The wall of muscle separating the left side from the right side of the heart. It prevents oxygenated and deoxygenated blood from mixing.",example:"隔膜",image_url:"",emoji:"🫀"},{word:"Single circulatory system",phonetic:"",meaning:"A circulatory system in which the blood travels one circuit. Blood flows through the heart and is pumped around the body before returning to the heart. Single circulatory systems are found in fish.",example:"单循环系统",image_url:"",emoji:"🫀"},{word:"Tricuspid valves",phonetic:"",meaning:"The atrioventricular valves found between the right atrium and right ventricle.",example:"三尖瓣",image_url:"",emoji:"🫀"},{word:"Valves",phonetic:"",meaning:"Structures in the heart that prevent the backflow of blood.",example:"瓣膜",image_url:"",emoji:"🫀"},{word:"Vein",phonetic:"",meaning:"A type of blood vessel that carries blood towards the heart under low pressure. It has a wide lumen, smooth inner lining and valves. The walls of the veins contain some smooth muscle and little elastic fibre.",example:"静脉",image_url:"",emoji:"🫀"},{word:"Vena cava",phonetic:"",meaning:"The vein that returns deoxygenated blood to the heart from the body.",example:"腔静脉",image_url:"",emoji:"🫀"},{word:"Ventricles",phonetic:"",meaning:"The two lower chambers of the heart that receive blood from the atria and expel blood into the arteries. The muscular wall of the left ventricle is thicker than that of the right ventricle.",example:"心室",image_url:"",emoji:"🫀"},{word:"White blood cells",phonetic:"",meaning:"Cells of the immune system that protect the body from invading pathogens. They play a role in phagocytosis and in the production of antibodies. Two types: phagocytes and lymphocytes.",example:"白细胞",image_url:"",emoji:"🫀"}]},{key:"caie-bio-topic13",name:"CAIE生物 · Topic 13 人体排泄",description:"人体排泄 · 16 个术语定义（IGCSE 生物）",words:[{word:"Assimilation",phonetic:"",meaning:"The movement of simple food molecules into the cells of the body where they are used.",example:"同化作用",image_url:"",emoji:"🚽"},{word:"Cortex",phonetic:"",meaning:"The outer region of the kidney.",example:"皮层",image_url:"",emoji:"🚽"},{word:"Deamination",phonetic:"",meaning:"The removal of the amino group from a molecule. In the liver, amino acids are deaminated to form ammonia, which is then converted to urea.",example:"脱氨基作用",image_url:"",emoji:"🚽"},{word:"Excretion",phonetic:"",meaning:"The process of removing metabolic waste from an organism. Excretory products include urea, carbon dioxide, excess water and salts.",example:"排泄",image_url:"",emoji:"🚽"},{word:"Glomerulus",phonetic:"",meaning:"A bundle of capillaries located in the renal capsule of a nephron adapted for the filtration of glucose, urea, water and salts from the blood.",example:"肾小球",image_url:"",emoji:"🚽"},{word:"Kidney",phonetic:"",meaning:"One of a pair of organs in the abdomen that has a role in the excretion of urea and excess water and salts.",example:"肾脏",image_url:"",emoji:"🚽"},{word:"Liver",phonetic:"",meaning:"The organ in which digested food molecules are assimilated. It is also involved in deamination.",example:"肝脏",image_url:"",emoji:"🚽"},{word:"Medulla",phonetic:"",meaning:"The inner region of the kidney.",example:"髓质",image_url:"",emoji:"🚽"},{word:"Nephron",phonetic:"",meaning:"The functional unit of the kidney consisting of a single glomerulus with a renal capsule, renal tubule and capillaries.",example:"肾单位",image_url:"",emoji:"🚽"},{word:"Renal arteries",phonetic:"",meaning:"Blood vessels that carry oxygenated blood to the kidneys.",example:"肾动脉",image_url:"",emoji:"🚽"},{word:"Renal tubule",phonetic:"",meaning:"The coiled region of the nephron which joins to a collecting duct. All glucose, most water and some salts are reabsorbed into the blood in the renal tubule.",example:"肾小管",image_url:"",emoji:"🚽"},{word:"Renal veins",phonetic:"",meaning:"Blood vessels that drain the kidneys.",example:"肾静脉",image_url:"",emoji:"🚽"},{word:"Urea",phonetic:"",meaning:"A toxic chemical produced from the breakdown of excess amino acids in the liver.",example:"尿素",image_url:"",emoji:"🚽"},{word:"Ureter",phonetic:"",meaning:"A tube that takes urine to the bladder from the kidneys.",example:"输尿管",image_url:"",emoji:"🚽"},{word:"Urethra",phonetic:"",meaning:"A tube that releases urine from the bladder, out of the body.",example:"尿道",image_url:"",emoji:"🚽"},{word:"Urine",phonetic:"",meaning:"The waste product of the kidneys that contains urea, excess water and excess ions. The volume and concentration of urine depends on water intake, exercise and temperature.",example:"尿液",image_url:"",emoji:"🚽"}]},{key:"caie-bio-topic14",name:"CAIE生物 · Topic 14 协调与反应",description:"协调与反应 · 66 个术语定义（IGCSE 生物）",words:[{word:"Accomodation",phonetic:"",meaning:"The process by which the elastic lens changes its shape (with the aid of ciliary muscles and suspensory ligaments) to focus on near or distant objects. Light is focused onto the retina.",example:"视觉调节",image_url:"",emoji:"🧠"},{word:"Adrenal glands",phonetic:"",meaning:"Endocrine glands located above the kidneys that produce adrenaline.",example:"肾上腺",image_url:"",emoji:"🧠"},{word:"Adrenaline",phonetic:"",meaning:"A hormone produced by the adrenal glands that is involved in the ‘fight or flight’ response. It increases heart rate, breathing rate and widens the pupils. Adrenaline also increases blood glucose concentration.",example:"肾上腺素",image_url:"",emoji:"🧠"},{word:"Antagonistic muscles",phonetic:"",meaning:"Pairs of muscles that work in an opposing fashion e.g. circular and radial muscles.",example:"拮抗肌",image_url:"",emoji:"🧠"},{word:"Auxins",phonetic:"",meaning:"A group of plant hormones that stimulate growth in shoot tips. They are involved in plant tropisms.",example:"生长素",image_url:"",emoji:"🧠"},{word:"Blind spot",phonetic:"",meaning:"The area at the back of the eye where the optic nerve exits the eye. It lacks receptor cells so cannot detect an image.",example:"盲点",image_url:"",emoji:"🧠"},{word:"Central nervous system (CNS)",phonetic:"",meaning:"The brain and spinal cord.",example:"中枢神经系统（CNS）",image_url:"",emoji:"🧠"},{word:"Ciliary muscle",phonetic:"",meaning:"A ring of smooth muscle that controls the shape of the lens.",example:"睫状肌",image_url:"",emoji:"🧠"},{word:"Circular muscles",phonetic:"",meaning:"Muscles of the iris that are involved in the pupil reflex action. In bright light, the circular muscles contract to constrict the pupil. Less light enters the eye.",example:"环形肌",image_url:"",emoji:"🧠"},{word:"Cone cells",phonetic:"",meaning:"Cells found in the retina that are sensitive to high light intensity (bright light). There are three types of cone cells that can detect light of different colours.",example:"视锥细胞",image_url:"",emoji:"🧠"},{word:"Cornea",phonetic:"",meaning:"The transparent outer covering of the eye which refracts light entering the eye.",example:"角膜",image_url:"",emoji:"🧠"},{word:"Effector",phonetic:"",meaning:"An organ, tissue, or cell that produces a response to a stimulus.",example:"效应器",image_url:"",emoji:"🧠"},{word:"Endocrine glands",phonetic:"",meaning:"Glands of the endocrine system that secrete hormones directly into the bloodstream.",example:"内分泌腺",image_url:"",emoji:"🧠"},{word:"Endocrine system",phonetic:"",meaning:"A collection of glands that secrete hormones into the bloodstream. Transmission of signals is slow and the effects are long-lasting.",example:"内分泌系统",image_url:"",emoji:"🧠"},{word:"Fovea",phonetic:"",meaning:"A region of the retina with a high density of cone cells.",example:"中央凹",image_url:"",emoji:"🧠"},{word:"Glucagon",phonetic:"",meaning:"A hormone secreted by the pancreas when blood glucose concentration is too low. It causes the breakdown of glycogen to glucose in the liver.",example:"胰高血糖素",image_url:"",emoji:"🧠"},{word:"Gravitropism",phonetic:"",meaning:"A plant's growth response to gravity.",example:"向地性",image_url:"",emoji:"🧠"},{word:"Hair erector muscles",phonetic:"",meaning:"Tiny muscles found in the skin which contract causing hairs to stand erect.",example:"立毛肌",image_url:"",emoji:"🧠"},{word:"Homeostasis",phonetic:"",meaning:"The maintenance of a stable internal environment in the body (within set limits) despite fluctuations in internal and external conditions.",example:"稳态",image_url:"",emoji:"🧠"},{word:"Hormone",phonetic:"",meaning:"A cell signalling molecule produced by endocrine glands and released into the blood. It travels to a target organ and binds to receptors on effectors, initiating a response.",example:"激素",image_url:"",emoji:"🧠"},{word:"Hypothalamus",phonetic:"",meaning:"A structure in the brain that contains the thermoregulatory centre. It coordinates information from the receptors and sends instructions to the effectors.",example:"下丘脑",image_url:"",emoji:"🧠"},{word:"Insulin",phonetic:"",meaning:"A hormone secreted by the pancreas when blood glucose concentration is too high. It causes liver and muscle cells to increase their uptake of glucose and the conversion of glucose to glycogen in the liver.",example:"胰岛素",image_url:"",emoji:"🧠"},{word:"Involuntary action",phonetic:"",meaning:"An action that does not involve conscious thought. Also known as a reflex action.",example:"不随意动作",image_url:"",emoji:"🧠"},{word:"Iris",phonetic:"",meaning:"A pigmented ring of circular and radial muscles. It controls the size of the pupil to alter how much light enters the eye.",example:"虹膜",image_url:"",emoji:"🧠"},{word:"Lens",phonetic:"",meaning:"The transparent structure at the front of the eye which refracts light, focusing it onto the retina. The lens is attached to a ring of ciliary muscle via suspensory ligaments.",example:"晶状体",image_url:"",emoji:"🧠"},{word:"Motor neurone",phonetic:"",meaning:"A neurone that carries nerve impulses from the CNS to the effectors.",example:"运动神经元",image_url:"",emoji:"🧠"},{word:"Negative feedback",phonetic:"",meaning:"A corrective mechanism that allows only small shifts from a set point, reversing a change in conditions.",example:"负反馈",image_url:"",emoji:"🧠"},{word:"Negative plant tropism",phonetic:"",meaning:"The growth of a plant away from a stimulus.",example:"负向向性",image_url:"",emoji:"🧠"},{word:"Nerve impulse",phonetic:"",meaning:"An electrical signal that travels along neurones.",example:"神经冲动",image_url:"",emoji:"🧠"},{word:"Nervous system",phonetic:"",meaning:"A collection of nerves and neurones involved in the transmission of electrical impulses. Transmission of signals is rapid and the effects are short-lived.",example:"神经系统",image_url:"",emoji:"🧠"},{word:"Neurone",phonetic:"",meaning:"A specialised cell that transmits nerve impulses. Also known as a nerve cell.",example:"神经元",image_url:"",emoji:"🧠"},{word:"Neurotransmitter",phonetic:"",meaning:"Chemicals that are used for communication between neurones and their target cells. Neurotransmitters are stored in synaptic vesicles in the presynaptic neurone and released into the synaptic cleft.",example:"神经递质",image_url:"",emoji:"🧠"},{word:"Oestrogen",phonetic:"",meaning:"A female sex hormone released by the ovaries that is involved in the development of the female secondary sexual characteristics. It also causes the growth and repair of the uterus lining during the menstrual cycle.",example:"雌激素",image_url:"",emoji:"🧠"},{word:"Optic nerve",phonetic:"",meaning:"A nerve at the back of the eye that transmits nerve impulses to the brain from the retina.",example:"视神经",image_url:"",emoji:"🧠"},{word:"Ovaries",phonetic:"",meaning:"A pair of endocrine glands in females that secrete oestrogen into the bloodstream.",example:"卵巢",image_url:"",emoji:"🧠"},{word:"Pancreas",phonetic:"",meaning:"An endocrine gland situated behind the stomach that produces insulin.",example:"胰腺",image_url:"",emoji:"🧠"},{word:"Peripheral nervous system",phonetic:"",meaning:"Pairs of nerves that originate from the CNS and carry nerve impulses into and out of the CNS.",example:"外周神经系统",image_url:"",emoji:"🧠"},{word:"Phototropism",phonetic:"",meaning:"A plant's growth response to light.",example:"向光性",image_url:"",emoji:"🧠"},{word:"Plant tropism",phonetic:"",meaning:"The growth response of a plant to a stimulus.",example:"植物向性",image_url:"",emoji:"🧠"},{word:"Positive plant tropism",phonetic:"",meaning:"The growth of a plant towards a stimulus.",example:"正向向性",image_url:"",emoji:"🧠"},{word:"Pupil",phonetic:"",meaning:"The aperture of the iris through which light rays enter the eye.",example:"瞳孔",image_url:"",emoji:"🧠"},{word:"Pupil reflex",phonetic:"",meaning:"A type of reflex action. The size of the pupil changes in response to exposure of the eye to different light intensities. Pupil size is controlled by the antagonistic circular and radial muscles in the iris.",example:"瞳孔反射",image_url:"",emoji:"🧠"},{word:"Radial muscles",phonetic:"",meaning:"Muscles of the iris that are involved in the pupil reflex action. In dim light, the radial muscles contract to dilate the pupil. More light enters the eye.",example:"放射肌",image_url:"",emoji:"🧠"},{word:"Receptor",phonetic:"",meaning:"A specialised structure that detects a specific type of stimulus.",example:"感受器",image_url:"",emoji:"🧠"},{word:"Reflex",phonetic:"",meaning:"A rapid, automatic response to a sensory stimulus by the body. It serves as a protective mechanism.",example:"反射",image_url:"",emoji:"🧠"},{word:"Reflex arc",phonetic:"",meaning:"The pathway of neurones involved in a reflex action:",example:"反射弧",image_url:"",emoji:"🧠"},{word:"Relay neurone",phonetic:"",meaning:"A neurone located in the spinal cord that links the sensory neurone to the motor neurone.",example:"中间神经元",image_url:"",emoji:"🧠"},{word:"Retina",phonetic:"",meaning:"A specialised layer at the back of the eye composed of light receptors. It converts light energy into neural signals which are sent to the brain via the optic nerve.",example:"视网膜",image_url:"",emoji:"🧠"},{word:"Rod cells",phonetic:"",meaning:"Cells in the retina that are sensitive to low light intensity (dim light).",example:"视杆细胞",image_url:"",emoji:"🧠"},{word:"Sense organ",phonetic:"",meaning:"A group of specialised receptor cells that respond to certain stimuli. The five sense organs are the eyes, ears, nose, skin and tongue.",example:"感觉器官",image_url:"",emoji:"🧠"},{word:"Sensory neurone",phonetic:"",meaning:"A neurone that carries nerve impulses from the receptors to the CNS.",example:"感觉神经元",image_url:"",emoji:"🧠"},{word:"Shivering",phonetic:"",meaning:"The involuntary contraction of muscles which generates heat from respiration.",example:"颤抖",image_url:"",emoji:"🧠"},{word:"Stimulus",phonetic:"",meaning:"A change in an organism’s internal or external environment that can be detected.",example:"刺激",image_url:"",emoji:"🧠"},{word:"Suspensory ligaments",phonetic:"",meaning:"A series of fibres that attach the lens to a ring of ciliary muscle.",example:"悬韧带",image_url:"",emoji:"🧠"},{word:"Sweat glands",phonetic:"",meaning:"Small tubular structures that secrete sweat onto the surface of the skin.",example:"汗腺",image_url:"",emoji:"🧠"},{word:"Sweating",phonetic:"",meaning:"The secretion of sweat onto the surface of the skin by sweat glands. The evaporation of water in sweat removes heat energy from the skin.",example:"出汗",image_url:"",emoji:"🧠"},{word:"Synapse",phonetic:"",meaning:"The junction between two nerve cells or a nerve cell and an effector that ensures nerve impulses can travel in one direction only.",example:"突触",image_url:"",emoji:"🧠"},{word:"Synaptic cleft",phonetic:"",meaning:"A small gap between neurones across which a nerve impulse is transmitted via neurotransmitters.",example:"突触间隙",image_url:"",emoji:"🧠"},{word:"Synaptic vesicles",phonetic:"",meaning:"Secretory vesicles located in the presynaptic neurone that store neurotransmitters and release them into the synaptic cleft on arrival of a nerve impulse.",example:"突触小泡",image_url:"",emoji:"🧠"},{word:"Testes",phonetic:"",meaning:"A pair of endocrine glands in males which secrete testosterone into the bloodstream.",example:"睾丸",image_url:"",emoji:"🧠"},{word:"Testosterone",phonetic:"",meaning:"A male sex hormone released by the testes that is involved in the development of the male secondary sexual characteristics.",example:"睾酮",image_url:"",emoji:"🧠"},{word:"Thermoregulatory centre",phonetic:"",meaning:"An area of the hypothalamus that regulates body temperature. It contains receptors sensitive to blood temperature.",example:"体温调节中枢",image_url:"",emoji:"🧠"},{word:"Type 1 diabetes",phonetic:"",meaning:"A type of diabetes in which the pancreas fails to produce enough insulin. It is controlled using daily insulin injections, limiting refined sugar intake and getting regular exercise.",example:"1型糖尿病",image_url:"",emoji:"🧠"},{word:"Vasoconstriction",phonetic:"",meaning:"Constriction of arterioles near the surface of the skin. Less blood flows close to the skin surface, decreasing heat loss to the surroundings.",example:"血管收缩",image_url:"",emoji:"🧠"},{word:"Vasodilation",phonetic:"",meaning:"Dilation of arterioles near the surface of the skin. This allows blood to flow closer to the skin surface, increasing heat loss to the surroundings.",example:"血管舒张",image_url:"",emoji:"🧠"},{word:"Voluntary action",phonetic:"",meaning:"An action that involves conscious thought.",example:"随意动作",image_url:"",emoji:"🧠"}]},{key:"caie-bio-topic15",name:"CAIE生物 · Topic 15 药物",description:"药物 · 4 个术语定义（IGCSE 生物）",words:[{word:"Antibiotic",phonetic:"",meaning:"A chemical or compound produced by a living organism that kills or prevents the growth of bacteria. Antibiotics have no effect on the cells of the host organism or viruses.",example:"抗生素",image_url:"",emoji:"💊"},{word:"Antibiotic-resistant bacteria",phonetic:"",meaning:"Bacteria that mutate to become resistant to an antibiotic, survive and reproduce very rapidly, passing on their antibiotic resistance.",example:"抗生素耐药菌",image_url:"",emoji:"💊"},{word:"Drug",phonetic:"",meaning:"A substance that when introduced into the body, alters the body’s chemical reactions.",example:"药物",image_url:"",emoji:"💊"},{word:"MRSA",phonetic:"",meaning:"A type of bacteria commonly found in hospitals that is resistant to almost all antibiotics.",example:"耐甲氧西林金黄色葡萄球菌（MRSA）",image_url:"",emoji:"💊"}]},{key:"caie-bio-topic16",name:"CAIE生物 · Topic 16 生殖",description:"生殖 · 49 个术语定义（IGCSE 生物）",words:[{word:"Abstinence",phonetic:"",meaning:"Deliberately refraining from having sexual intercourse.",example:"禁欲（节欲）",image_url:"",emoji:"👶"},{word:"Acquired immunodeficiency syndrome (AIDS)",phonetic:"",meaning:"A disease which occurs when HIV destroys a given proportion of lymphocytes and the immune system is no longer functional.",example:"艾滋病（AIDS）",image_url:"",emoji:"👶"},{word:"Amniotic fluid",phonetic:"",meaning:"The liquid surrounding the embryo in the amniotic sac that protects the fetus and acts as a shock absorber.",example:"羊水",image_url:"",emoji:"👶"},{word:"Amniotic sac",phonetic:"",meaning:"A thin, transparent bag which holds the developing fetus and amniotic fluid.",example:"羊膜囊",image_url:"",emoji:"👶"},{word:"Anther",phonetic:"",meaning:"The pollen-bearing structure of the stamen.",example:"花药",image_url:"",emoji:"👶"},{word:"Asexual reproduction",phonetic:"",meaning:"A form of reproduction involving a single parent that creates genetically identical offspring.",example:"无性生殖",image_url:"",emoji:"👶"},{word:"Carpel",phonetic:"",meaning:"The female part of the plant consisting of a stigma, style and ovary.",example:"雌蕊",image_url:"",emoji:"👶"},{word:"Cervix",phonetic:"",meaning:"A narrow opening into the uterus that protects the fetus.",example:"子宫颈",image_url:"",emoji:"👶"},{word:"Cross-pollination",phonetic:"",meaning:"A type of pollination in which pollen is transferred from an anther of one plant to a stigma of a different plant. This results in plants with greater genetic diversity.",example:"异花传粉",image_url:"",emoji:"👶"},{word:"Egg cell",phonetic:"",meaning:"A specialised female sex cell involved in reproduction. It has a haploid nucleus, a large amount of cytoplasm rich in fats and proteins, and is surrounded by a jelly coat. Also known as an ovum.",example:"卵细胞",image_url:"",emoji:"👶"},{word:"Fertilisation",phonetic:"",meaning:"The fusion of the nucleus of male and female gametes. It restores the full chromosome number.",example:"受精",image_url:"",emoji:"👶"},{word:"Fetus",phonetic:"",meaning:"An embryo after eight weeks of development.",example:"胎儿",image_url:"",emoji:"👶"},{word:"Follicle-stimulating hormone (FSH)",phonetic:"",meaning:"A hormone secreted by the pituitary gland that binds to follicle cells, stimulating them to mature and secrete oestrogen.",example:"促卵泡激素（FSH）",image_url:"",emoji:"👶"},{word:"Gametes",phonetic:"",meaning:"Sex cells (sperm and egg cells) with half the usual number of chromosomes. The nuclei of gametes are haploid.",example:"配子",image_url:"",emoji:"👶"},{word:"Germination",phonetic:"",meaning:"The process by which a plant grows from a seed.",example:"萌发",image_url:"",emoji:"👶"},{word:"Human immunodeficiency virus (HIV)",phonetic:"",meaning:"An infectious virus that is spread by direct contact with infected body fluids. It destroys lymphocytes, impairing the ability to produce antibodies and weakening the immune system. HIV may lead to AIDS.",example:"人类免疫缺陷病毒（HIV）",image_url:"",emoji:"👶"},{word:"Implantation",phonetic:"",meaning:"The early stage of pregnancy in which the embryo adheres and sinks into the wall of the uterus.",example:"着床",image_url:"",emoji:"👶"},{word:"Insect-pollinated flower",phonetic:"",meaning:"A type of flower that relies on insects to transfer pollen grains between flowers.",example:"虫媒花",image_url:"",emoji:"👶"},{word:"Luteinising hormone (LH)",phonetic:"",meaning:"A hormone secreted by the pituitary gland that initiates ovulation and stimulates the development of the remains of the follicle into a corpus luteum.",example:"黄体生成素（LH）",image_url:"",emoji:"👶"},{word:"Menstrual cycle",phonetic:"",meaning:"The monthly cycle in women that involves the development of the uterus lining, ovulation, maintenance of the uterus lining and its shedding.",example:"月经周期",image_url:"",emoji:"👶"},{word:"Oestrogen",phonetic:"",meaning:"A female sex hormone released by the ovaries that is involved in the development of the female secondary sexual characteristics. It also causes the growth and repair of the uterus lining in the menstrual cycle. High levels of oestrogen stimulate a surge in LH production.",example:"雌激素",image_url:"",emoji:"👶"},{word:"Ovary (human)",phonetic:"",meaning:"An organ in the female reproductive system that produces egg cells in follicles.",example:"卵巢（人体）",image_url:"",emoji:"👶"},{word:"Ovary (flower)",phonetic:"",meaning:"Part of the carpel that holds the ovules and following fertilisation, develops into the fruit.",example:"子房（花）",image_url:"",emoji:"👶"},{word:"Oviducts",phonetic:"",meaning:"The tubes that transport egg cells from the ovaries to the uterus. They are the site of fertilisation.",example:"输卵管",image_url:"",emoji:"👶"},{word:"Penis",phonetic:"",meaning:"The male sex organ that penetrates the vagina and releases sperm.",example:"阴茎",image_url:"",emoji:"👶"},{word:"Petals",phonetic:"",meaning:"Structures that surround the reproductive parts of a flower. They are often brightly coloured and fragrant to attract insects.",example:"花瓣",image_url:"",emoji:"👶"},{word:"Placenta",phonetic:"",meaning:"A temporary organ attached to the lining of the uterus during pregnancy. It has a variety of roles including the exchange of gases, nutrients and excretory products between fetal and maternal blood, hormonal control, and serving as a barrier to pathogens and toxins.",example:"胎盘",image_url:"",emoji:"👶"},{word:"Pollen grain",phonetic:"",meaning:"A single granule of pollen that contains the male gamete. In wind-pollinated plants, grains are small and produced in large numbers, whereas in insect-pollinated plants, they are large, sticky and produced in fewer numbers.",example:"花粉粒",image_url:"",emoji:"👶"},{word:"Pollen tube",phonetic:"",meaning:"A hollow tube that grows from a pollen grain to the embryo sac in the ovule after pollination. It delivers the male gametes.",example:"花粉管",image_url:"",emoji:"👶"},{word:"Progesterone",phonetic:"",meaning:"A female sex hormone secreted by the corpus luteum that maintains the uterus lining. It also inhibits FSH and LH release.",example:"孕酮",image_url:"",emoji:"👶"},{word:"Prostate gland",phonetic:"",meaning:"A gland located between the bladder and the penis that secretes an alkaline fluid to neutralise vaginal acidity.",example:"前列腺",image_url:"",emoji:"👶"},{word:"Rubella",phonetic:"",meaning:"An infection (known as the German measles) caused by the Rubella virus. Pregnant women who contract rubella are at risk of a miscarriage or still-birth.",example:"风疹",image_url:"",emoji:"👶"},{word:"Scrotum",phonetic:"",meaning:"A pouch of skin that holds the testes and maintains an optimum temperature for sperm production.",example:"阴囊",image_url:"",emoji:"👶"},{word:"Self-pollination",phonetic:"",meaning:"A type of pollination in which pollen is transferred from an anther of a plant to a stigma of the same plant. This results in plants with less genetic diversity.",example:"自花传粉",image_url:"",emoji:"👶"},{word:"Sepals",phonetic:"",meaning:"Modified leaves that surround and protect the flower when it is in the bud.",example:"萼片",image_url:"",emoji:"👶"},{word:"Sexually transmitted infections (STI)",phonetic:"",meaning:"A group of infections (e.g. HIV) that are transmitted via bodily fluids through sexual contact or intercourse.",example:"性传播感染（STI）",image_url:"",emoji:"👶"},{word:"Sexual reproduction",phonetic:"",meaning:"A form of reproduction involving the fusion of male and female gametes to form a zygote. It creates genetic variation.",example:"有性生殖",image_url:"",emoji:"👶"},{word:"Sperm cell",phonetic:"",meaning:"A specialised male sex cell involved in reproduction. It consists of a head containing the acrosome and haploid nucleus, a midpiece containing many mitochondria and a flagellum.",example:"精子细胞",image_url:"",emoji:"👶"},{word:"Sperm duct",phonetic:"",meaning:"The tube that transfers sperm from the epididymis during ejaculation.",example:"输精管",image_url:"",emoji:"👶"},{word:"Stamen",phonetic:"",meaning:"The male part of the plant consisting of an anther and a filament. It is involved in the production of male gametes in the form of pollen grains.",example:"雄蕊",image_url:"",emoji:"👶"},{word:"Stigma",phonetic:"",meaning:"The sticky structure of the carpel that receives pollen grains.",example:"柱头",image_url:"",emoji:"👶"},{word:"Testes",phonetic:"",meaning:"A pair of organs in the male reproductive system that produce sperm and testosterone.",example:"睾丸",image_url:"",emoji:"👶"},{word:"Testosterone",phonetic:"",meaning:"A male sex hormone released by the testes that is involved in the development of the male secondary sexual characteristics.",example:"睾酮",image_url:"",emoji:"👶"},{word:"Umbilical cord",phonetic:"",meaning:"A tube containing blood vessels that connects the fetus to the placenta.",example:"脐带",image_url:"",emoji:"👶"},{word:"Urethra",phonetic:"",meaning:"The tube responsible for the transfer of urine during urination (in both males and females) and semen during ejaculation (in males).",example:"尿道",image_url:"",emoji:"👶"},{word:"Uterus",phonetic:"",meaning:"The organ in the female reproductive system in which the embryo develops.",example:"子宫",image_url:"",emoji:"👶"},{word:"Vagina",phonetic:"",meaning:"The muscular canal that extends from the cervix to the outside of the body. During sexual intercourse it stimulates the penis to ejaculate.",example:"阴道",image_url:"",emoji:"👶"},{word:"Wind-pollinated flower",phonetic:"",meaning:"A type of flower that relies on wind to transfer pollen grains between flowers.",example:"风媒花",image_url:"",emoji:"👶"},{word:"Zygote",phonetic:"",meaning:"A cell formed via the fusion of a male and female gamete. The nucleus of a zygote is diploid.",example:"受精卵",image_url:"",emoji:"👶"}]},{key:"caie-bio-topic17",name:"CAIE生物 · Topic 17 遗传",description:"遗传 · 31 个术语定义（IGCSE 生物）",words:[{word:"Allele",phonetic:"",meaning:"A version of a gene.",example:"等位基因",image_url:"",emoji:"🧬"},{word:"Blood group",phonetic:"",meaning:"Classification of blood type as A, B, AB or O based on surface antigens on red blood cells and the presence of certain antibodies in the plasma. Blood group is controlled by three alleles, IA, IB and IO.",example:"血型",image_url:"",emoji:"🧬"},{word:"Chromosome",phonetic:"",meaning:"A long, coiled molecule of DNA that carries genetic information in the form of genes.",example:"染色体",image_url:"",emoji:"🧬"},{word:"Codominance",phonetic:"",meaning:"When both alleles for a gene in a heterozygous organism equally contribute to the phenotype.",example:"共显性",image_url:"",emoji:"🧬"},{word:"Colour blindness",phonetic:"",meaning:"An X-linked recessive condition characterised by the inability to distinguish between colours. It is more common among males because they only inherit one X chromosome.",example:"色盲",image_url:"",emoji:"🧬"},{word:"Diploid cell",phonetic:"",meaning:"A cell that contains a pair of each chromosome type e.g. human diploid cell has 23 pairs of chromosomes.",example:"二倍体细胞",image_url:"",emoji:"🧬"},{word:"Diploid nucleus",phonetic:"",meaning:"A nucleus that contains two copies of each chromosome (i.e. a full set of chromosomes).",example:"二倍体细胞核",image_url:"",emoji:"🧬"},{word:"Dominant",phonetic:"",meaning:"Describes an allele that is always expressed. Represented by a capital letter.",example:"显性",image_url:"",emoji:"🧬"},{word:"Gametes",phonetic:"",meaning:"Sex cells (sperm and egg cells) with half the usual number of chromosomes.",example:"配子",image_url:"",emoji:"🧬"},{word:"Gene",phonetic:"",meaning:"A length of DNA on a chromosome that codes for the production of a specific protein.",example:"基因",image_url:"",emoji:"🧬"},{word:"Gene expression",phonetic:"",meaning:"All specialised cells contain the same set of genes, but only the genes required to code for certain proteins are switched on in any given cell.",example:"基因表达",image_url:"",emoji:"🧬"},{word:"Genetic code",phonetic:"",meaning:"The rules by which the sequence of bases in a gene codes for the sequence of amino acids in a specific protein.",example:"遗传密码",image_url:"",emoji:"🧬"},{word:"Genotype",phonetic:"",meaning:"An organism’s genetic composition. Describes all alleles.",example:"基因型",image_url:"",emoji:"🧬"},{word:"Haploid nucleus",phonetic:"",meaning:"A nucleus that contains a single copy of each chromosome (i.e. half the number of chromosomes)",example:"单倍体细胞核",image_url:"",emoji:"🧬"},{word:"Heterozygous",phonetic:"",meaning:"When someone has two different alleles of a gene e.g. Ff.",example:"杂合的",image_url:"",emoji:"🧬"},{word:"Homozygous",phonetic:"",meaning:"When someone has two identical alleles of a gene e.g. ff.",example:"纯合的",image_url:"",emoji:"🧬"},{word:"Inheritance",phonetic:"",meaning:"The transmission of genetic information from one generation to the next.",example:"遗传",image_url:"",emoji:"🧬"},{word:"Meiosis",phonetic:"",meaning:"A form of nuclear division that produces four genetically different daughter cells (gametes). It involves two divisions. Chromosome number is halved, resulting in haploid cells.",example:"减数分裂",image_url:"",emoji:"🧬"},{word:"Mitosis",phonetic:"",meaning:"A form of nuclear division that produces two genetically identical daughter cells from one parent cell. The copies of chromosomes are separated, maintaining the diploid chromosome number. Mitosis is important in the growth, repair and replacement of cells, as well as asexual reproduction.",example:"有丝分裂",image_url:"",emoji:"🧬"},{word:"Monohybrid inheritance",phonetic:"",meaning:"The inheritance of a single gene. mRNA - A polymer of nucleotides that carries genetic information from the nucleus to the ribosomes during protein synthesis.",example:"单因子遗传",image_url:"",emoji:"🧬"},{word:"Pedigree diagram",phonetic:"",meaning:"A chart used to show the inheritance of a given characteristic in a family.",example:"系谱图",image_url:"",emoji:"🧬"},{word:"Phenotype",phonetic:"",meaning:"An organism’s observable characteristics due to interactions of the genotype and the environment.",example:"表现型",image_url:"",emoji:"🧬"},{word:"Punnett square",phonetic:"",meaning:"A grid used to predict the potential outcomes of a genetic cross.",example:"庞尼特方格",image_url:"",emoji:"🧬"},{word:"Pure breeding",phonetic:"",meaning:"A type of breeding in which all of the offspring carry the same phenotype as the parents. This occurs when two identical homozygous individuals are crossed.",example:"纯种繁育",image_url:"",emoji:"🧬"},{word:"Recessive",phonetic:"",meaning:"Describes an allele that is only expressed in the absence of a dominant allele. Represented by a small letter.",example:"隐性",image_url:"",emoji:"🧬"},{word:"Ribosomes",phonetic:"",meaning:"Sub-cellular structures that are the site of protein synthesis.",example:"核糖体",image_url:"",emoji:"🧬"},{word:"Sex chromosomes",phonetic:"",meaning:"A pair of chromosomes responsible for the determination of gender. XY in males, XX in females.",example:"性染色体",image_url:"",emoji:"🧬"},{word:"Sex-linked characteristic",phonetic:"",meaning:"A characteristic that is coded for by an allele found on a sex chromosome.",example:"伴性遗传特征",image_url:"",emoji:"🧬"},{word:"Stem cells",phonetic:"",meaning:"Cells that are unspecialised and capable of dividing by mitosis to produce a range of different cell types.",example:"干细胞",image_url:"",emoji:"🧬"},{word:"Test cross",phonetic:"",meaning:"An individual with a dominant phenotype is crossed with a homozygous recessive individual. The ratio of offspring indicates the genotype of the dominant individual.",example:"测交",image_url:"",emoji:"🧬"},{word:"Variation",phonetic:"",meaning:"The differences between individuals due to genes, the environment or a combination of both.",example:"变异",image_url:"",emoji:"🧬"}]},{key:"caie-bio-topic18",name:"CAIE生物 · Topic 18 变异与选择",description:"变异与选择 · 20 个术语定义（IGCSE 生物）",words:[{word:"Adaptation",phonetic:"",meaning:"The process by which populations over many generations become increasingly suited to their environment, as a result of natural selection.",example:"适应",image_url:"",emoji:"🦎"},{word:"Adaptive feature",phonetic:"",meaning:"An inherited feature of an organism that increases its chance of survival and reproduction in its environment.",example:"适应性特征",image_url:"",emoji:"🦎"},{word:"Antibiotic-resistant bacteria",phonetic:"",meaning:"Bacteria that mutate to become resistant to an antibiotic, survive and reproduce very rapidly, passing on their antibiotic resistance.",example:"抗生素耐药菌",image_url:"",emoji:"🦎"},{word:"Artificial selection",phonetic:"",meaning:"See ‘selective breeding’.",example:"人工选择",image_url:"",emoji:"🦎"},{word:"Competition",phonetic:"",meaning:"When different organisms compete for the same resources (e.g. light, water, mates) in an ecosystem. This limits population sizes and stimulates evolutionary change.",example:"竞争",image_url:"",emoji:"🦎"},{word:"Continuous variation",phonetic:"",meaning:"A type of variation that cannot be categorised e.g. skin colour, height. It produces a continuous range in which a phenotype can take any value between two extremes. It is affected by environmental conditions.",example:"连续变异",image_url:"",emoji:"🦎"},{word:"Discontinuous variation",phonetic:"",meaning:"A type of variation that can be categorised e.g. blood group, tongue rolling. A characteristic can only appear in discrete values. It is generally influenced by genes alone.",example:"不连续变异",image_url:"",emoji:"🦎"},{word:"Evolution",phonetic:"",meaning:"The gradual change in the adaptive features of a population over time. Occurs due to natural selection.",example:"进化",image_url:"",emoji:"🦎"},{word:"Fitness",phonetic:"",meaning:"The ability of an organism to survive and reproduce in its environment.",example:"适合度",image_url:"",emoji:"🦎"},{word:"Gene mutation",phonetic:"",meaning:"A random change in the base sequence of DNA which may result in genetic variants. Mutations may be beneficial, damaging or neutral.",example:"基因突变",image_url:"",emoji:"🦎"},{word:"Genetic variation",phonetic:"",meaning:"Differences in the genotypes of organisms of the same species due to the presence of different alleles, arising through mutations and sexual reproduction. It creates variation in phenotypes.",example:"遗传变异",image_url:"",emoji:"🦎"},{word:"Hydrophytes",phonetic:"",meaning:"Plants that are adapted to live and reproduce in very wet habitats e.g. water lilies.",example:"水生植物",image_url:"",emoji:"🦎"},{word:"Mutagen",phonetic:"",meaning:"A chemical, biological or physical agent that increases the rate of gene mutations above normal level e.g. ionising radiation.",example:"诱变剂",image_url:"",emoji:"🦎"},{word:"Mutation",phonetic:"",meaning:"A genetic change. Mutations may form new alleles.",example:"突变",image_url:"",emoji:"🦎"},{word:"Natural selection",phonetic:"",meaning:"The process by which the frequency of advantageous traits passed on in genes gradually increases in a population over time.",example:"自然选择",image_url:"",emoji:"🦎"},{word:"Phenotypic variation",phonetic:"",meaning:"Differences in the phenotypes of organisms of the same species. Due to interactions of the genotype and the environment.",example:"表现型变异",image_url:"",emoji:"🦎"},{word:"Population",phonetic:"",meaning:"All organisms of the same species living with one another in a habitat.",example:"种群",image_url:"",emoji:"🦎"},{word:"Selective breeding",phonetic:"",meaning:"The process by which humans artificially select organisms with desirable characteristics and breed them to produce offspring with desirable phenotypes. Also known as artificial selection.",example:"选择育种",image_url:"",emoji:"🦎"},{word:"Variation",phonetic:"",meaning:"Differences between individuals of the same species.",example:"变异",image_url:"",emoji:"🦎"},{word:"Xerophytes",phonetic:"",meaning:"Plants that are adapted to live and reproduce in dry habitats where water availability is low e.g. cacti and marram grass.",example:"旱生植物",image_url:"",emoji:"🦎"}]},{key:"caie-bio-topic19",name:"CAIE生物 · Topic 19 生物与环境",description:"生物与环境 · 47 个术语定义（IGCSE 生物）",words:[{word:"Biomass",phonetic:"",meaning:"The total mass of organic material measured in a specific area over a set period.",example:"生物量",image_url:"",emoji:"🌍"},{word:"Carbon cycle",phonetic:"",meaning:"The cycle through which carbon (in the form of carbon dioxide) moves between living organisms and the environment. It involves respiration, photosynthesis, feeding, combustion, decomposition and fossilisation.",example:"碳循环",image_url:"",emoji:"🌍"},{word:"Carnivore",phonetic:"",meaning:"An animal that feeds on other animals.",example:"肉食动物",image_url:"",emoji:"🌍"},{word:"Carrying Capacity",phonetic:"",meaning:"The maximum population size that an environment can support.",example:"环境容纳量",image_url:"",emoji:"🌍"},{word:"Combustion",phonetic:"",meaning:"The scientific term for the burning of a substance.",example:"燃烧",image_url:"",emoji:"🌍"},{word:"Community",phonetic:"",meaning:"All of the populations of different species living together in a habitat.",example:"群落",image_url:"",emoji:"🌍"},{word:"Consumers",phonetic:"",meaning:"Organisms that feed on other organisms to obtain energy.",example:"消费者",image_url:"",emoji:"🌍"},{word:"Deamination",phonetic:"",meaning:"A process that occurs in the liver in which the amino group is removed from amino acids to produce ammonia, later converted to urea.",example:"脱氨基作用",image_url:"",emoji:"🌍"},{word:"Death phase",phonetic:"",meaning:"A period of population reduction in which the mortality rate is greater than the reproduction rate.",example:"衰亡期",image_url:"",emoji:"🌍"},{word:"Decomposers",phonetic:"",meaning:"Organisms that obtain energy via the breakdown of dead plant and animal material into simpler organic matter.",example:"分解者",image_url:"",emoji:"🌍"},{word:"Decomposition",phonetic:"",meaning:"The breakdown of dead materials into simpler organic matter.",example:"分解作用",image_url:"",emoji:"🌍"},{word:"Deforestation",phonetic:"",meaning:"The removal of trees from land which is subsequently used to grow crops or provide space for cattle.",example:"森林砍伐",image_url:"",emoji:"🌍"},{word:"Denitrification",phonetic:"",meaning:"The conversion of nitrate ions to nitrogen gas by denitrifying bacteria.",example:"反硝化作用",image_url:"",emoji:"🌍"},{word:"Denitrifying bacteria",phonetic:"",meaning:"Microorganisms responsible for the conversion of nitrate ions to nitrogen gas.",example:"反硝化细菌",image_url:"",emoji:"🌍"},{word:"Ecosystem",phonetic:"",meaning:"The community of organisms and non-living components of an area and their interactions.",example:"生态系统",image_url:"",emoji:"🌍"},{word:"Food chain",phonetic:"",meaning:"Describes the feeding relationships between organisms and the resultant stages of biomass transfer. It takes the form: producer ⟶ primary consumer ⟶ secondary consumer ⟶ tertiary consumer",example:"食物链",image_url:"",emoji:"🌍"},{word:"Food web",phonetic:"",meaning:"A diagram showing the interactions of different food chains.",example:"食物网",image_url:"",emoji:"🌍"},{word:"Fossil",phonetic:"",meaning:"The remains of dead organisms found in rocks which are millions of years old.",example:"化石",image_url:"",emoji:"🌍"},{word:"Fossil fuel",phonetic:"",meaning:"A fuel (e.g. coal, oil, natural gas) formed from the compression of carbon-containing plant or animal remains over millions of years.",example:"化石燃料",image_url:"",emoji:"🌍"},{word:"Fossilisation",phonetic:"",meaning:"The process by which a fossil is formed.",example:"化石化",image_url:"",emoji:"🌍"},{word:"Herbivore",phonetic:"",meaning:"An animal that feeds on plants.",example:"草食动物",image_url:"",emoji:"🌍"},{word:"Ingestion",phonetic:"",meaning:"The process by which organisms take food and drink into their bodies through the mouth. In a food chain, energy is transferred between organisms by ingestion.",example:"摄入",image_url:"",emoji:"🌍"},{word:"Lag phase",phonetic:"",meaning:"A period of slow population growth.",example:"延滞期",image_url:"",emoji:"🌍"},{word:"Light energy",phonetic:"",meaning:"The main source of energy input to biological systems that is harnessed from the sun. Light energy is trapped by photosynthetic organisms and converted to chemical energy.",example:"光能",image_url:"",emoji:"🌍"},{word:"Log phase",phonetic:"",meaning:"A period of rapid population growth, characterised by the birth rate exceeding the death rate. Also known as the exponential phase.",example:"对数期",image_url:"",emoji:"🌍"},{word:"Nitrification",phonetic:"",meaning:"The conversion of ammonium ions to nitrate ions by nitrifying bacteria. This takes place in two stages: ammonium ions are oxidised to nitrite ions; nitrite ions are oxidised to nitrate ions.",example:"硝化作用",image_url:"",emoji:"🌍"},{word:"Nitrifying bacteria",phonetic:"",meaning:"Microorganisms found in the soil responsible for the conversion of ammonium ions into nitrite and then nitrate ions.",example:"硝化细菌",image_url:"",emoji:"🌍"},{word:"Nitrogen cycle",phonetic:"",meaning:"The cycle through which nitrogen moves between living organisms and the environment, involving four types of bacteria: decomposers, nitrifying bacteria, nitrogen-fixing bacteria and denitrifying bacteria.",example:"氮循环",image_url:"",emoji:"🌍"},{word:"Nitrogen fixation",phonetic:"",meaning:"The conversion of atmospheric nitrogen gas into ammonia by nitrogen-fixing bacteria in the soil or root nodules of legumes. It can also occur via lightning.",example:"固氮作用",image_url:"",emoji:"🌍"},{word:"Nitrogen-fixing bacteria",phonetic:"",meaning:"Microorganisms responsible for the conversion of atmospheric nitrogen gas into nitrogen-containing compounds. They can be free-living or mutualistic.",example:"固氮细菌",image_url:"",emoji:"🌍"},{word:"Over-harvesting",phonetic:"",meaning:"The harvesting of a species (for food, materials etc.) resulting in a reduction in population numbers. This may lead to the species becoming endangered or extinct.",example:"过度捕捞/采集",image_url:"",emoji:"🌍"},{word:"Photosynthesis",phonetic:"",meaning:"A reaction that takes place inside photosynthetic organisms (e.g. plants, algae) and manufactures carbohydrates from raw materials using light energy.",example:"光合作用",image_url:"",emoji:"🌍"},{word:"Population",phonetic:"",meaning:"All organisms of the same species living with one another in a particular habitat, at the same time.",example:"种群",image_url:"",emoji:"🌍"},{word:"Population growth curve",phonetic:"",meaning:"A graphical representation of changing population numbers over time. The curve of a growing population in an environment with limited resources has a sigmoidal shape.",example:"种群增长曲线",image_url:"",emoji:"🌍"},{word:"Predators",phonetic:"",meaning:"Consumers that prey on and eat other animals.",example:"捕食者",image_url:"",emoji:"🌍"},{word:"Prey",phonetic:"",meaning:"Animals that are eaten by predators.",example:"猎物",image_url:"",emoji:"🌍"},{word:"Primary consumers",phonetic:"",meaning:"Herbivores at trophic level two of a food chain that consume producers.",example:"初级消费者",image_url:"",emoji:"🌍"},{word:"Producers",phonetic:"",meaning:"Photosynthetic organisms (e.g. green plants or algae) at the start of the food chain that provide biomass for all living things.",example:"生产者",image_url:"",emoji:"🌍"},{word:"Pyramid of biomass",phonetic:"",meaning:"A table of the dry mass of living material at each trophic level of a food chain. This forms the shape of a pyramid.",example:"生物量金字塔",image_url:"",emoji:"🌍"},{word:"Pyramids of energy",phonetic:"",meaning:"A diagram which shows the amount of energy within the biomass of organisms at each trophic level.",example:"能量金字塔",image_url:"",emoji:"🌍"},{word:"Pyramid of numbers",phonetic:"",meaning:"A diagram that shows the number of individual organisms at each trophic level of a food chain.",example:"数量金字塔",image_url:"",emoji:"🌍"},{word:"Quaternary consumers",phonetic:"",meaning:"Carnivores that are at the top of a food chain.",example:"四级消费者",image_url:"",emoji:"🌍"},{word:"Respiration",phonetic:"",meaning:"A chemical reaction that takes place in cells and produces energy from nutrient molecules.",example:"呼吸作用",image_url:"",emoji:"🌍"},{word:"Secondary consumers",phonetic:"",meaning:"Carnivores at trophic level three of a food chain that consume herbivores.",example:"次级消费者",image_url:"",emoji:"🌍"},{word:"Stationary phase",phonetic:"",meaning:"A period of stability in which population numbers generally remain constant.",example:"稳定期",image_url:"",emoji:"🌍"},{word:"Tertiary consumers",phonetic:"",meaning:"Carnivores at trophic level four of a food chain that consume other carnivores.",example:"三级消费者",image_url:"",emoji:"🌍"},{word:"Trophic level",phonetic:"",meaning:"The position that an organism holds in a food chain, food web, pyramid of numbers or pyramid of biomass.",example:"营养级",image_url:"",emoji:"🌍"}]},{key:"caie-bio-topic20",name:"CAIE生物 · Topic 20 人类对生态系统的影响",description:"人类对生态系统的影响 · 26 个术语定义（IGCSE 生物）",words:[{word:"Agricultural machinery",phonetic:"",meaning:"Machinery used in farming to improve efficiency by clearing land, preparing soil, and maintaining and harvesting crops.",example:"农业机械",image_url:"",emoji:"♻️"},{word:"Captive breeding program",phonetic:"",meaning:"The breeding of endangered animals in enclosures (such as zoos) to increase population numbers and preserve biodiversity.",example:"圈养繁殖计划",image_url:"",emoji:"♻️"},{word:"Chemical fertilisers",phonetic:"",meaning:"Mineral salts (e.g. ammonium sulfate, NPK) that are added to soils to provide essential nutrients and improve plant growth.",example:"化肥",image_url:"",emoji:"♻️"},{word:"Climate change",phonetic:"",meaning:"The long-term changes in the Earth’s weather patterns.",example:"气候变化",image_url:"",emoji:"♻️"},{word:"Conservation",phonetic:"",meaning:"The maintenance of ecosystems and biodiversity by humans in order to preserve the Earth’s resources.",example:"保护（生物保护）",image_url:"",emoji:"♻️"},{word:"Deforestation",phonetic:"",meaning:"The removal of trees from land which is subsequently used to grow crops or provide space for cattle. Removal of forests can lead to extinction, soil erosion, flooding and global warming.",example:"森林砍伐",image_url:"",emoji:"♻️"},{word:"Endangered",phonetic:"",meaning:"Describes a species that is at risk of extinction due to loss of habitat or rapid decrease in population numbers.",example:"濒危的",image_url:"",emoji:"♻️"},{word:"Eutrophication",phonetic:"",meaning:"The process by which pollution by nitrogen-containing fertilisers results in algal blooms and subsequent oxygen level reduction in bodies of water.",example:"富营养化",image_url:"",emoji:"♻️"},{word:"Extinction",phonetic:"",meaning:"The death of all living members of a species.",example:"灭绝",image_url:"",emoji:"♻️"},{word:"Fossil fuel",phonetic:"",meaning:"A non-renewable fuel (e.g. coal, oil, natural gas) formed from the compression of carbon-containing plant or animal remains over millions of years.",example:"化石燃料",image_url:"",emoji:"♻️"},{word:"Global warming",phonetic:"",meaning:"The gradual rise in the average temperature of the Earth due to increasing atmospheric levels of carbon dioxide and methane gas.",example:"全球变暖",image_url:"",emoji:"♻️"},{word:"Greenhouse effect",phonetic:"",meaning:"The increase of global temperatures caused by the trapping of solar heat by insular gases in the atmosphere.",example:"温室效应",image_url:"",emoji:"♻️"},{word:"Habitat destruction",phonetic:"",meaning:"The process by which a natural habitat can no longer support the species present. This may be due to human actions such as increasing urbanisation, the extraction of natural resources and marine pollution.",example:"栖息地破坏",image_url:"",emoji:"♻️"},{word:"Herbicides",phonetic:"",meaning:"Chemicals that are used to kill weeds.",example:"除草剂",image_url:"",emoji:"♻️"},{word:"Insecticides",phonetic:"",meaning:"Chemicals that are used to kill insects.",example:"杀虫剂",image_url:"",emoji:"♻️"},{word:"Intensive livestock production",phonetic:"",meaning:"A type of intensive farming (also known as factory farming) that maximises production whilst minimising associated costs. This includes zero grazing, antibiotic treatments and harvesting animals before adulthood.",example:"集约化畜牧生产",image_url:"",emoji:"♻️"},{word:"Legal quotas",phonetic:"",meaning:"A means of managing and regulating the amount of resources that can be taken from the environment, e.g. commercial fishing quotas or logging quotas.",example:"法定配额",image_url:"",emoji:"♻️"},{word:"Monoculture",phonetic:"",meaning:"The agricultural practice of harvesting only one species of crop at a time.",example:"单一栽培",image_url:"",emoji:"♻️"},{word:"Natural fertilisers",phonetic:"",meaning:"Natural materials (e.g. manure) that are added to soils to provide essential nutrients and improve plant growth.",example:"天然肥料",image_url:"",emoji:"♻️"},{word:"Non-biodegradable plastic",phonetic:"",meaning:"Plastic that cannot be broken down naturally by decomposers.",example:"不可降解塑料",image_url:"",emoji:"♻️"},{word:"Non-renewable resource",phonetic:"",meaning:"A resource that is in finite supply and which will eventually run out.",example:"不可再生资源",image_url:"",emoji:"♻️"},{word:"Pollution",phonetic:"",meaning:"Contamination or destruction of the natural environment due to human intervention. Sources of pollution include fertilisers, pesticides, chemical waste, nuclear fall-out, discarded rubbish and untreated sewage.",example:"污染",image_url:"",emoji:"♻️"},{word:"Seed bank",phonetic:"",meaning:"A storage of viable seeds to protect biodiversity.",example:"种子库",image_url:"",emoji:"♻️"},{word:"Selective breeding",phonetic:"",meaning:"The process by which humans artificially select organisms with desirable characteristics and breed them to produce offspring with desirable phenotypes.",example:"选择育种",image_url:"",emoji:"♻️"},{word:"Soil erosion",phonetic:"",meaning:"The movement of the upper layer of soil due to the action of water.",example:"水土流失",image_url:"",emoji:"♻️"},{word:"Sustainable resource",phonetic:"",meaning:"A resource that is never depleted. It is produced as quickly as it is removed from the environment.",example:"可持续资源",image_url:"",emoji:"♻️"}]},{key:"caie-bio-topic21",name:"CAIE生物 · Topic 21 生物技术与基因工程",description:"生物技术与基因工程 · 20 个术语定义（IGCSE 生物）",words:[{word:"Anaerobic respiration",phonetic:"",meaning:"Respiration that takes place without oxygen and forms energy from the breakdown of glucose. In muscles, lactic acid is produced. In yeast, alcohol and carbon dioxide are produced. Less energy is released than in aerobic respiration.",example:"无氧呼吸",image_url:"",emoji:"🧫"},{word:"Antibiotic",phonetic:"",meaning:"A chemical or compound produced by a living organism that kills or prevents the growth of bacteria, e.g. penicillin.",example:"抗生素",image_url:"",emoji:"🧫"},{word:"Biofuel",phonetic:"",meaning:"A renewable energy source that is produced from biomass.",example:"生物燃料",image_url:"",emoji:"🧫"},{word:"Biological washing powder",phonetic:"",meaning:"A type of detergent that contains enzymes (e.g. proteases, lipases) which remove stains by digesting large, insoluble food molecules.",example:"生物洗衣粉",image_url:"",emoji:"🧫"},{word:"Biotechnology",phonetic:"",meaning:"The field of biology involving the use of living systems to produce or transform materials. It has applications in agriculture, medicine and food science. Bacteria are useful in biotechnology.",example:"生物技术",image_url:"",emoji:"🧫"},{word:"DNA ligase",phonetic:"",meaning:"An enzyme used to insert a specific gene into a plasmid (by joining their complementary sticky ends) to form a recombinant plasmid.",example:"DNA连接酶",image_url:"",emoji:"🧫"},{word:"Fermentation",phonetic:"",meaning:"The chemical breakdown of a substance (normally under anaerobic conditions) by microorganisms or enzymes.",example:"发酵",image_url:"",emoji:"🧫"},{word:"Fermenter",phonetic:"",meaning:"A large tank in which fermentation takes place. It is filled with a nutrient solution and maintained at an optimum pH (using mineral salts) and temperature.",example:"发酵罐",image_url:"",emoji:"🧫"},{word:"Genetically modified (GM) organism",phonetic:"",meaning:"An organism that has had its genome altered.",example:"转基因生物（GM）",image_url:"",emoji:"🧫"},{word:"Genetic engineering",phonetic:"",meaning:"The modification of the genome of an organism by the insertion of a desired gene from another organism, enabling the formation of organisms with beneficial characteristics.",example:"基因工程",image_url:"",emoji:"🧫"},{word:"Lactase",phonetic:"",meaning:"An enzyme that breaks down lactose into glucose and galactose. It is used in the production of lactose-free milk.",example:"乳糖酶",image_url:"",emoji:"🧫"},{word:"Pectin",phonetic:"",meaning:"A polysaccharide found in plant cell walls that holds the walls of adjacent cells together.",example:"果胶",image_url:"",emoji:"🧫"},{word:"Pectinase",phonetic:"",meaning:"An enzyme used in the production of fruit juice. Pectinase breaks down pectin, releasing the contents of cells and increasing the yield of fruit juice. It is also used to clarify fruit juice and wine.",example:"果胶酶",image_url:"",emoji:"🧫"},{word:"Penicillin",phonetic:"",meaning:"The first conventional, effective and safe antibiotic derived from the mould Penicillium.",example:"青霉素",image_url:"",emoji:"🧫"},{word:"Penicillium",phonetic:"",meaning:"A species of fungus responsible for the production of the antibiotic penicillin.",example:"青霉属",image_url:"",emoji:"🧫"},{word:"Plasmids",phonetic:"",meaning:"Pieces of circular DNA found in bacteria that are used to transfer genetic material between cells.",example:"质粒",image_url:"",emoji:"🧫"},{word:"Recombinant DNA",phonetic:"",meaning:"A combination of DNA from two different organisms.",example:"重组DNA",image_url:"",emoji:"🧫"},{word:"Restriction enzymes",phonetic:"",meaning:"Enzymes that cut DNA molecules at specific sequences, creating sticky ends.",example:"限制酶",image_url:"",emoji:"🧫"},{word:"Sticky ends",phonetic:"",meaning:"The staggered cut formed by restriction enzymes in double-stranded DNA.",example:"黏性末端",image_url:"",emoji:"🧫"},{word:"Yeast",phonetic:"",meaning:"A microorganism which canrespire anaerobically to release carbon dioxide and ethanol. Yeast is used in bread-making to make dough rise as bubbles of carbon dioxide form.It is also used to make ethanol for biofuels.",example:"酵母菌",image_url:"",emoji:"🧫"}]}];export{e as CAIE_BIOLOGY_BANKS_MORE};
